import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

// Initialize Admin Client (Bypassing RLS for Cron Jobs)
// Client initialization moved to handler

export const dynamic = 'force-dynamic'; // Ensure it runs dynamically

export async function GET(request: Request) {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY!;
  const supabase = createClient(supabaseUrl, supabaseServiceKey);
  // 1. Security Check (Optional: Add API Key header check here)
  /*
  const authHeader = request.headers.get('authorization');
  if (authHeader !== `Bearer ${process.env.CRON_SECRET}`) {
    return new NextResponse('Unauthorized', { status: 401 });
  }
  */

  try {
    const now = new Date();
    const results = {
      birthdays: 0,
      reminders: 0,
      reviews: 0,
      errors: [] as string[]
    };

    // --- A. BIRTHDAY TRIGGERS ---
    const { data: birthdayRules } = await supabase
      .from('notification_rules')
      .select('*')
      .eq('is_active', true)
      .eq('trigger_type', 'birthday');

    if (birthdayRules?.length) {
      // Find clients with birthday today
      // Note: This is simplified. In prod, careful with Timezones and Leap Years.
      const todayMMDD = now.toISOString().slice(5, 10); // "MM-DD"
      
      const { data: birthdayClients } = await supabase
        .from('clients')
        .select('*')
        .eq('status', 'active'); // Assuming there's a status

      // Filter in memory for simplicity in this MVP (SQL 'to_char' better for large scale)
      const celebrants = birthdayClients?.filter(c => 
        c.birth_date && c.birth_date.endsWith(todayMMDD)
      ) || [];

      for (const rule of birthdayRules) {
        for (const client of celebrants) {
          if (client.company_id !== rule.company_id) continue;

          // Check if already sent today
          const startOfDay = new Date(now.setHours(0,0,0,0)).toISOString();
          const { count } = await supabase
            .from('notifications')
            .select('*', { count: 'exact', head: true })
            .eq('rule_id', rule.id)
            .eq('client_id', client.id)
            .gte('created_at', startOfDay);

          if (count === 0) {
            // Queue Notification
            const message = rule.message_template.replace('{cliente}', client.full_name.split(' ')[0]);
            await supabase.from('notifications').insert({
              company_id: rule.company_id,
              client_id: client.id,
              rule_id: rule.id,
              destination: client.phone,
              message_content: message,
              status: 'pending', // Logic to send immediately or later
              scheduled_for: new Date().toISOString()
            });
            results.birthdays++;
          }
        }
      }
    }

    // --- B. PRE-APPOINTMENT (Reminders) ---
    // Example: 24h before (time_offset -1440)
    // We look for appointments starting between [TargetTime - 15min] and [TargetTime + 15min]
    const { data: reminderRules } = await supabase
      .from('notification_rules')
      .select('*')
      .eq('is_active', true)
      .eq('trigger_type', 'pre_appointment');

    if (reminderRules?.length) {
      for (const rule of reminderRules) {
        // Calculate target window
        // Rule: -1440 min (24h before). If Now is 10:00, we want appointments tomorrow at 10:00.
        // Appointment Time = Now + Abs(offset)
        const offsetMinutes = Math.abs(rule.time_offset_minutes);
        const targetTimeStart = new Date(now.getTime() + (offsetMinutes * 60000) - (15 * 60000)); // -15 min tolerance
        const targetTimeEnd = new Date(now.getTime() + (offsetMinutes * 60000) + (15 * 60000));   // +15 min tolerance

        const { data: appointments } = await supabase
          .from('appointments')
          .select('*, clients(full_name, phone), profiles(full_name)')
          .eq('status', 'confirmed')
          .eq('company_id', rule.company_id)
          .gte('start_time', targetTimeStart.toISOString())
          .lte('start_time', targetTimeEnd.toISOString());

        if (appointments) {
          for (const appt of appointments) {
            // Check duplicates
             const { count } = await supabase
              .from('notifications')
              .select('*', { count: 'exact', head: true })
              .eq('rule_id', rule.id)
              .eq('appointment_id', appt.id);
            
            if (count === 0) {
              let message = rule.message_template
                .replace('{cliente}', appt.clients?.full_name.split(' ')[0] || 'Cliente')
                .replace('{profissional}', appt.profiles?.full_name.split(' ')[0] || 'Profissional')
                .replace('{hora}', new Date(appt.start_time).toLocaleTimeString('pt-BR', {hour: '2-digit', minute:'2-digit'}));

              await supabase.from('notifications').insert({
                company_id: rule.company_id,
                client_id: appt.client_id,
                appointment_id: appt.id,
                rule_id: rule.id,
                destination: appt.clients?.phone || '',
                message_content: message,
                status: 'pending',
                scheduled_for: new Date().toISOString()
              });
              results.reminders++;
            }
          }
        }
      }
    }

    return NextResponse.json({ success: true, processed: results });
  } catch (error: any) {
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

'use client';

import { useEffect, useState } from 'react';
import { Card, CardContent, Button } from '@projeto/ui';
import { CheckCircle2, XCircle, Calendar, Clock } from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

export default function ConfirmAppointmentPage({ params }: { params: { token: string } }) {
  const [loading, setLoading] = useState(true);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [appointment, setAppointment] = useState<any>(null);

  useEffect(() => {
    confirm();
  }, [params.token]);

  async function confirm() {
    try {
      const res = await fetch('/api/appointments/confirm', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ token: params.token })
      });
      
      const data = await res.json();

      if (!res.ok) throw new Error(data.error || 'Erro ao confirmar');

      setAppointment(data.appointment);
      setSuccess(true);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  if (loading) return (
     <div className="min-h-screen flex items-center justify-center bg-[#FDFBF7]">
        <span className="animate-pulse text-[#D4AF37] font-bold">Verificando...</span>
     </div>
  );

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#FDFBF7] p-4 font-sans">
       <Card className="w-full max-w-md bg-white border-[#E5E0D8] shadow-2xl rounded-3xl overflow-hidden">
          <CardContent className="p-8 text-center space-y-6">
             {success ? (
                <>
                   <div className="mx-auto w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center text-emerald-500 animate-scale-in">
                      <CheckCircle2 className="h-10 w-10" />
                   </div>
                   <h1 className="text-2xl font-bold text-[#2C2825]">Presença Confirmada!</h1>
                   <p className="text-[#5C5855]">Obrigado por confirmar seu agendamento.</p>
                   
                   {appointment && (
                      <div className="bg-[#FAF9F6] border border-[#E5E0D8] rounded-2xl p-4 text-left space-y-3">
                         <div className="flex items-center gap-3">
                            <Calendar className="h-5 w-5 text-[#D4AF37]" />
                            <div>
                               <p className="text-xs text-[#8A847C] font-bold uppercase">Data</p>
                               <p className="text-[#2C2825] font-medium capitalize">
                                  {format(new Date(appointment.start_time), "EEEE, dd 'de' MMMM", { locale: ptBR })}
                               </p>
                            </div>
                         </div>
                         <div className="flex items-center gap-3">
                            <Clock className="h-5 w-5 text-[#D4AF37]" />
                            <div>
                               <p className="text-xs text-[#8A847C] font-bold uppercase">Horário</p>
                               <p className="text-[#2C2825] font-medium">
                                  {format(new Date(appointment.start_time), "HH:mm")}
                               </p>
                            </div>
                         </div>
                      </div>
                   )}
                </>
             ) : (
                <>
                   <div className="mx-auto w-20 h-20 bg-red-50 rounded-full flex items-center justify-center text-red-500">
                      <XCircle className="h-10 w-10" />
                   </div>
                   <h1 className="text-2xl font-bold text-[#2C2825]">Erro na Confirmação</h1>
                   <p className="text-neutral-500">{error}</p>
                </>
             )}
          </CardContent>
       </Card>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { Button, Badge, Card, CardContent } from '@projeto/ui';
import { CheckCircle2, XCircle, ShieldAlert, Loader2, Crown, Clock, Users } from 'lucide-react';

interface Profile {
  id: string;
  email: string;
  full_name: string;
  role: string;
  approved: boolean;
  created_at: string;
  companies?: { name: string } | null;
}

export default function AdminUsersPage() {
  const [users, setUsers] = useState<Profile[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);

  const supabase = createBrowserClient();

  const fetchUsers = useCallback(async () => {
    setLoading(true);

    // Obter o ID do usuário logado para proteger o super admin
    const { data: { user } } = await supabase.auth.getUser();
    if (user) setCurrentUserId(user.id);

    // Buscar todos os perfis com o nome da empresa
    const { data, error } = await supabase
      .from('profiles')
      .select('*, companies(name)')
      .order('approved', { ascending: true })  // Pendentes primeiro
      .order('created_at', { ascending: false });

    if (error) {
      console.error('[ADMIN] Erro ao buscar usuários:', error.message);
    } else {
      setUsers(data || []);
    }
    setLoading(false);
  }, []);

  useEffect(() => { fetchUsers(); }, [fetchUsers]);

  const toggleApproval = async (id: string, currentStatus: boolean, targetRole: string) => {
    // Proteger o super_admin de ser bloqueado acidentalmente
    if (targetRole === 'super_admin') {
      alert('O Super Admin não pode ter seu acesso alterado.');
      return;
    }
    // Não pode bloquear a si mesmo
    if (id === currentUserId) {
      alert('Você não pode bloquear o seu próprio acesso.');
      return;
    }

    setActionLoading(id);
    const newStatus = !currentStatus;

    const { error } = await supabase
      .from('profiles')
      .update({ approved: newStatus })
      .eq('id', id);

    if (error) {
      console.error('[ADMIN] Erro ao atualizar perfil:', error.message);
      alert('Erro ao atualizar usuário. Verifique as permissões RLS.');
    } else {
      console.log('[ADMIN] Acesso atualizado. Novo status:', newStatus ? 'aprovado' : 'bloqueado');
      setUsers(prev => prev.map(u => u.id === id ? { ...u, approved: newStatus } : u));
    }
    setActionLoading(null);
  };

  const pending = users.filter(u => !u.approved && u.role !== 'super_admin');
  const approved = users.filter(u => u.approved);

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-[#D4AF37]" />
      </div>
    );
  }

  return (
    <div className="space-y-8 max-w-5xl mx-auto">
      {/* Header */}
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight text-[#2C2825]">Gerenciamento de Acessos</h1>
        <p className="text-[#8A847C]">Aprove ou bloqueie o acesso das clínicas cadastradas.</p>
      </div>

      {/* Contadores */}
      <div className="grid grid-cols-3 gap-4">
        <div className="bg-amber-50 border border-amber-100 rounded-2xl p-4 text-center">
          <Clock className="h-6 w-6 text-amber-500 mx-auto mb-1" />
          <div className="text-2xl font-bold text-amber-700">{pending.length}</div>
          <div className="text-xs text-amber-600 font-medium uppercase tracking-wide">Pendentes</div>
        </div>
        <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-4 text-center">
          <CheckCircle2 className="h-6 w-6 text-emerald-500 mx-auto mb-1" />
          <div className="text-2xl font-bold text-emerald-700">{approved.length}</div>
          <div className="text-xs text-emerald-600 font-medium uppercase tracking-wide">Aprovados</div>
        </div>
        <div className="bg-[#F5F0E8] border border-[#E5E0D8] rounded-2xl p-4 text-center">
          <Users className="h-6 w-6 text-[#8A847C] mx-auto mb-1" />
          <div className="text-2xl font-bold text-[#2C2825]">{users.length}</div>
          <div className="text-xs text-[#8A847C] font-medium uppercase tracking-wide">Total</div>
        </div>
      </div>

      {/* Lista de usuários */}
      <div className="grid gap-4">
        {users.length === 0 ? (
          <Card className="bg-white border-dashed border-2 border-neutral-200">
            <CardContent className="flex flex-col items-center justify-center py-12 text-center text-neutral-500">
              <ShieldAlert className="h-12 w-12 mb-4 opacity-50" />
              <p>Nenhum usuário encontrado.</p>
            </CardContent>
          </Card>
        ) : (
          users.map((user) => (
            <Card
              key={user.id}
              className={`overflow-hidden transition-all hover:shadow-md border-[#E5E0D8] ${
                !user.approved && user.role !== 'super_admin' ? 'border-l-4 border-l-amber-400' : ''
              }`}
            >
              <div className="p-5 flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
                <div className="flex items-start gap-4">
                  {/* Avatar */}
                  <div className={`w-11 h-11 rounded-full flex items-center justify-center text-base font-bold shrink-0 ${
                    user.role === 'admin'
                      ? 'bg-[#D4AF37]/20 text-[#B5952F]'
                      : user.approved
                        ? 'bg-emerald-100 text-emerald-700'
                        : 'bg-amber-100 text-amber-700'
                  }`}>
                    {user.role === 'super_admin'
                      ? <Crown className="h-5 w-5" />
                      : (user.full_name?.charAt(0).toUpperCase() || '?')
                    }
                  </div>

                  {/* Info */}
                  <div>
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="font-bold text-[#2C2825]">{user.full_name || 'Sem nome'}</h3>
                      {user.role === 'super_admin' && (
                        <span className="text-[10px] bg-[#D4AF37]/15 text-[#B5952F] border border-[#D4AF37]/30 px-2 py-0.5 rounded-full font-bold uppercase tracking-wider">
                          Super Admin
                        </span>
                      )}
                    </div>
                    <div className="text-sm text-[#8A847C] mt-0.5">{user.email}</div>
                    <div className="text-xs text-neutral-400 mt-1 flex items-center gap-2">
                      {user.companies?.name && (
                        <span className="font-medium text-[#5C5855]">🏥 {user.companies.name}</span>
                      )}
                      <span>·</span>
                      <span>Cadastro: {new Date(user.created_at).toLocaleDateString('pt-BR')}</span>
                    </div>
                  </div>
                </div>

                {/* Status + Ação */}
                <div className="flex items-center gap-3 w-full md:w-auto shrink-0">
                  <div className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${
                    user.role === 'admin'
                      ? 'bg-[#D4AF37]/10 text-[#B5952F] border border-[#D4AF37]/20'
                      : user.approved
                        ? 'bg-emerald-50 text-emerald-600 border border-emerald-100'
                        : 'bg-amber-50 text-amber-600 border border-amber-100'
                  }`}>
                    {user.role === 'super_admin' ? 'Master' : user.approved ? 'Aprovado' : 'Pendente'}
                  </div>

                  {user.role !== 'super_admin' && (
                    <Button
                      onClick={() => toggleApproval(user.id, user.approved, user.role)}
                      disabled={actionLoading === user.id}
                      className={`min-w-[130px] font-bold ${user.approved
                        ? 'bg-white border border-red-200 text-red-600 hover:bg-red-50'
                        : 'bg-[#D4AF37] hover:bg-[#B5952F] text-white shadow-sm shadow-[#D4AF37]/20'
                      }`}
                    >
                      {actionLoading === user.id ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : user.approved ? (
                        <><XCircle className="h-4 w-4 mr-1.5" />Bloquear</>
                      ) : (
                        <><CheckCircle2 className="h-4 w-4 mr-1.5" />Aprovar</>
                      )}
                    </Button>
                  )}
                </div>
              </div>
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { 
  Button, 
  Card, 
  CardContent, 
  CardHeader, 
  CardTitle,
  cn,
  Badge
} from '@projeto/ui';
import { 
  TrendingUp, 
  Package, 
  Activity, 
  Calendar, 
  TrendingDown, 
  ChevronRight,
  Filter,
  Users
} from 'lucide-react';
import Link from 'next/link';
import { RankingChart, EvolutionChart } from '@/components/analytics/analytics-charts';
import { useProfile } from '@/providers/profile-provider';
import { 
  startOfDay, 
  endOfDay, 
  startOfMonth, 
  endOfMonth, 
  startOfYear, 
  endOfYear,
  isWithinInterval,
  format,
  subDays,
  eachDayOfInterval
} from 'date-fns';
import { ptBR } from 'date-fns/locale';

type Period = 'today' | 'month' | 'year';

export default function AnalyticsPage() {
  const { profile } = useProfile();
  const [period, setPeriod] = useState<Period>('month');
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<{
    productRanking: any[];
    procedureRanking: any[];
    evolution: any[];
    totals: {
      products: number;
      procedures: number;
      revenue: number;
    };
    clientRanking: any[];
    averageAppointments: number;
    topClient: { name: string; value: number } | null;
  }>({
    productRanking: [],
    procedureRanking: [],
    evolution: [],
    totals: { products: 0, procedures: 0, revenue: 0 },
    clientRanking: [],
    averageAppointments: 0,
    topClient: null
  });

  useEffect(() => {
    if (profile?.company_id) {
      fetchAnalytics();
    }
  }, [profile, period]);

  async function fetchAnalytics() {
    setLoading(true);
    try {
      const supabase = createBrowserClient();

      // Get Date Range
      const now = new Date();
      let start: Date, end: Date;

      if (period === 'today') {
        start = startOfDay(now);
        end = endOfDay(now);
      } else if (period === 'month') {
        start = startOfMonth(now);
        end = endOfMonth(now);
      } else {
        start = startOfYear(now);
        end = endOfYear(now);
      }

      // Fetch Data in parallel
      const [productsRes, transactionsRes, appointmentsRes] = await Promise.all([
        supabase.from('products').select('*'),
        supabase.from('inventory_transactions').select('*, products(name, description)').eq('type', 'out'),
        supabase.from('appointments').select('*, procedures(name, price), clients(id, full_name)').eq('status', 'completed')
      ]);

      if (productsRes.error) throw productsRes.error;
      if (transactionsRes.error) throw transactionsRes.error;
      if (appointmentsRes.error) throw appointmentsRes.error;

      // Filter products (Resale only)
      const validProducts = transactionsRes.data?.filter(t => {
        const category = t.products?.description?.includes('Categoria: ') 
          ? t.products.description.split('Categoria: ')[1] 
          : '';
        return category !== 'Insumos' && isWithinInterval(new Date(t.created_at), { start, end });
      }) || [];

      // Filter appointments
      const validAppointments = appointmentsRes.data?.filter(a => 
        isWithinInterval(new Date(a.start_time), { start, end })
      ) || [];

      // Calculate Rankings
      const productMap: Record<string, number> = {};
      validProducts.forEach(t => {
        const name = t.products?.name || 'Inconhecido';
        productMap[name] = (productMap[name] || 0) + Number(t.quantity);
      });

      const procMap: Record<string, number> = {};
      validAppointments.forEach(a => {
        const name = a.procedures?.name || 'Inconhecido';
        procMap[name] = (procMap[name] || 0) + 1;
      });

      const productRanking = Object.entries(productMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 5);

      const procedureRanking = Object.entries(procMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 5);

      // Client Ranking & Stats
      const clientMap: Record<string, { name: string, count: number, total: number }> = {};
      validAppointments.forEach(a => {
        const clientId = a.clients?.id || 'unknown';
        const clientName = a.clients?.full_name || 'Cliente Particular';
        const price = a.price_override || a.procedures?.price || 0;

        if (!clientMap[clientId]) {
          clientMap[clientId] = { name: clientName, count: 0, total: 0 };
        }
        clientMap[clientId].count += 1;
        clientMap[clientId].total += Number(price);
      });

      const clientRanking = Object.values(clientMap)
        .sort((a, b) => b.count - a.count)
        .slice(0, 5)
        .map(c => ({ name: c.name, value: c.count, total: c.total }));

      const totalClients = Object.keys(clientMap).length;
      const averageAppointments = totalClients > 0 ? validAppointments.length / totalClients : 0;
      const topClient = clientRanking.length > 0 ? { name: clientRanking[0].name, value: clientRanking[0].value } : null;

      // Evolution Data (Last 7 points based on period)
      // For Month: last 7 days. For Year: last 7 months.
      const evolution: any[] = [];
      if (period !== 'year') {
        const days = eachDayOfInterval({ start: subDays(now, 6), end: now });
        days.forEach(day => {
          const dayStart = startOfDay(day);
          const dayEnd = endOfDay(day);

          const v = validProducts.filter(t => isWithinInterval(new Date(t.created_at), { start: dayStart, end: dayEnd })).length;
          const p = validAppointments.filter(a => isWithinInterval(new Date(a.start_time), { start: dayStart, end: dayEnd })).length;

          evolution.push({
            date: format(day, 'dd/MM'),
            vendas: v,
            procedimentos: p
          });
        });
      }

      // Totals
      const totalRevenue = validAppointments.reduce((acc, curr) => acc + (curr.price_override || curr.procedures?.price || 0), 0);

      setData({
        productRanking,
        procedureRanking,
        evolution,
        totals: {
          products: validProducts.length,
          procedures: validAppointments.length,
          revenue: totalRevenue
        },
        clientRanking,
        averageAppointments,
        topClient
      });
    } catch (err) {
      console.error('Error fetching analytics:', err);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      {/* Header */}
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-2xl shadow-xl shadow-slate-200 border border-slate-800">
            <TrendingUp className="h-8 w-8 text-emerald-500" />
          </div>
          <div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tight">Análises e Insights</h1>
