                    <div className="space-y-8">
                       {data.clientRanking.map((client, idx) => (
                          <div key={idx} className="flex items-center justify-between group">
                             <div className="flex items-center gap-6">
                                <div className={cn(
                                   "w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg transition-all shadow-sm",
                                   idx === 0 ? "bg-amber-100 text-amber-600 border border-amber-200" : 
                                   idx === 1 ? "bg-slate-100 text-slate-600 border border-slate-200" :
                                   idx === 2 ? "bg-orange-50 text-orange-600 border border-orange-100" :
                                   "bg-slate-50 text-slate-400 border border-slate-100"
                                )}>
                                   {idx + 1}
                                </div>
                                <div>
                                   <p className="text-base font-black text-slate-900 group-hover:text-rose-600 transition-colors uppercase tracking-tight">{client.name}</p>
                                   <div className="flex items-center gap-3 mt-1">
                                      <span className="text-[10px] font-bold text-slate-400 flex items-center gap-1">
                                         <Activity className="h-3 w-3" /> {client.value} Atendimentos
                                      </span>
                                      <div className="w-1 h-1 rounded-full bg-slate-200" />
                                      <span className="text-[10px] font-bold text-emerald-500 uppercase">
                                         {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(client.total)} investidos
                                      </span>
                                   </div>
                                </div>
                             </div>
                             <div className="flex flex-col items-end">
                                <div className="h-2 w-32 bg-slate-50 rounded-full overflow-hidden mt-2 border border-slate-100/50">
                                   <div 
                                      className={cn("h-full transition-all duration-1000", idx === 0 ? "bg-rose-500" : "bg-slate-300")} 
                                      style={{ width: `${(client.value / data.clientRanking[0].value) * 100}%` }}
                                   />
                                </div>
                             </div>
                          </div>
                       ))}
                    </div>
                  ) : (
                    <EmptyState message="Nenhum dado de cliente no período" />
                  )}
               </div>
               <div className="md:col-span-4 bg-slate-50/30 p-10 flex flex-col justify-center gap-10">
                  <div className="space-y-4">
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                        <Activity className="h-3 w-3 text-rose-500" /> Retenção Média
                     </p>
                     <div>
                        <h4 className="text-4xl font-black text-slate-950 italic">{data.averageAppointments.toFixed(1)}</h4>
                        <p className="text-[11px] font-medium text-slate-500 mt-1">Visitas por cliente no período</p>
                     </div>
                  </div>

                  <div className="h-px bg-slate-100 w-full" />

                  <div className="space-y-4">
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                        <TrendingUp className="h-3 w-3 text-emerald-500" /> Ticket Fidelidade
                     </p>
                     <div>
                        <h4 className="text-3xl font-black text-emerald-600 italic">
                           {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(
                              data.clientRanking.reduce((acc, curr) => acc + curr.total, 0) / (data.clientRanking.length || 1)
                           )}
                        </h4>
                        <p className="text-[11px] font-medium text-slate-500 mt-1">Gasto médio dos TOP 5 clientes</p>
                     </div>
                  </div>
               </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

function MetricCard({ title, value, icon: Icon, trend, color, className }: any) {
  const colors = {
    amber: 'text-white bg-amber-500 shadow-lg shadow-amber-200 border-amber-400',
    blue: 'text-white bg-blue-600 shadow-lg shadow-blue-200 border-blue-500',
    emerald: 'text-white bg-emerald-600 shadow-lg shadow-emerald-200 border-emerald-500',
    purple: 'text-white bg-purple-600 shadow-lg shadow-purple-200 border-purple-500'
  };

  return (
    <Card className={cn("bg-white border-neutral-100 rounded-3xl overflow-hidden shadow-lg shadow-slate-200/50 hover:scale-[1.02] transition-all duration-300", className)}>
      <CardContent className="p-6">
        <div className="flex items-center justify-between mb-4">
          <div className={cn("p-2.5 rounded-2xl border", colors[color as keyof typeof colors])}>
            <Icon className="h-5 w-5" />
          </div>
          <Badge variant="outline" className="text-[10px] font-black border-slate-100 text-slate-400 px-2 py-0">
            {trend}
          </Badge>
        </div>
        <div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
          <h3 className="text-2xl font-black text-slate-900 truncate">{value}</h3>
        </div>
      </CardContent>
    </Card>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="flex flex-col items-center justify-center h-full py-12 text-center">
      <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
        <TrendingDown className="h-8 w-8 text-slate-200" />
      </div>
      <p className="text-slate-400 font-bold text-sm">{message}</p>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { Button, Card, CardContent, Badge } from '@projeto/ui';
import { ArrowLeft, User, Calendar, CheckCircle2, FileText, Smartphone } from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import Link from 'next/link';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { toast } from 'sonner';

export default function AnamneseResponseDetailsPage() {
  const params = useParams();
  const router = useRouter();
  const [response, setResponse] = useState<any>(null);
  const [answers, setAnswers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (params.id) fetchDetails();
  }, [params.id]);

  async function fetchDetails() {
    try {
      const supabase = createBrowserClient();
      
      // 1. Fetch Response Header
      const { data: respData, error: respError } = await supabase
        .from('anamnese_responses')
        .select(`
          *,
          anamnese_templates (name, description),
          clients (full_name, phone, email, birth_date)
        `)
        .eq('id', params.id)
        .single();

      if (respError) throw respError;
      setResponse(respData);

      // 2. Fetch Answers with Question Text
      const { data: ansData, error: ansError } = await supabase
        .from('anamnese_answers')
        .select(`
          *,
          anamnese_questions (question_text, type)
        `)
        .eq('response_id', params.id)
        .order('created_at', { ascending: true }); // Or use question order if joined properly

      if (ansError) throw ansError;
      setAnswers(ansData || []);

    } catch (err) {
      console.error(err);
      toast.error('Erro ao carregar detalhes');
    } finally {
      setLoading(false);
    }
  }

  if (loading) return <div className="p-8 text-[#5C5855]">Carregando detalhes...</div>;
  if (!response) return <div className="p-8 text-[#5C5855]">Resposta não encontrada.</div>;

  return (
    <div className="space-y-6 max-w-4xl mx-auto pb-20">
       {/* Header */}
       <div className="flex items-center gap-4">
          <Link href="/dashboard/anamnese/responses">
             <Button variant="ghost" size="icon" className="text-[#2C2825] bg-button-hover rounded-xl">
                <ArrowLeft className="h-5 w-5" />
             </Button>
          </Link>
          <div>
             <div className="flex items-center gap-3">
                <h1 className="text-2xl font-black text-[#2C2825]">Detalhes da Anamnese</h1>
                <Badge className="bg-emerald-500/10 text-emerald-500 border-none">Concluído</Badge>
             </div>
             <p className="text-[#5C5855] text-sm">Visualizando respostas do paciente.</p>
          </div>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Sidebar Info */}
          <div className="space-y-6">
             {/* Cliente Info */}
             <Card className="bg-white border-[#E5E0D8] rounded-3xl">
                <CardContent className="p-6 space-y-4">
                   <div className="flex items-center gap-3">
                      <div className="h-10 w-10 rounded-full bg-[#FAF9F6] text-[#8A847C]">
                         <User className="h-5 w-5" />
                      </div>
                      <div>
                         <p className="text-xs text-neutral-400 font-bold uppercase">Paciente</p>
                         <p className="text-[#2C2825] font-bold">{response.clients?.full_name}</p>
                      </div>
                   </div>
                   
                   <div className="pt-4 border-t border-neutral-800 space-y-2 text-sm text-neutral-400">
                      <div className="flex items-center gap-2">
                         <Smartphone className="h-4 w-4" />
                         <span>{response.clients?.phone || 'Sem telefone'}</span>
                      </div>
                      <div className="flex items-center gap-2">
                         <Calendar className="h-4 w-4" />
                         <span>Nasc: {response.clients?.birth_date ? format(new Date(response.clients.birth_date), 'dd/MM/yyyy') : 'N/A'}</span>
                      </div>
                   </div>
                </CardContent>
             </Card>

             {/* Metadata */}
             <Card className="bg-white border-[#E5E0D8] rounded-3xl">
                <CardContent className="p-6 space-y-4">
                   <div>
                      <p className="text-xs text-neutral-400 font-bold uppercase mb-1">Modelo Utilizado</p>
                      <div className="flex items-center gap-2 text-[#2C2825] font-medium">
                         <FileText className="h-4 w-4 text-primary-500" />
                         {response.anamnese_templates?.name}
                      </div>
                   </div>
                   
                   <div>
                      <p className="text-xs text-neutral-400 font-bold uppercase mb-1">Data da Resposta</p>
                      <div className="flex items-center gap-2 text-[#2C2825] font-medium">
                         <CheckCircle2 className="h-4 w-4 text-emerald-500" />
                         {response.completed_at ? format(new Date(response.completed_at), "dd 'de' MMM, HH:mm", { locale: ptBR }) : 'Pendente'}
                      </div>
                   </div>
                </CardContent>
             </Card>
          </div>

          {/* Respostas (Main Content) */}
          <div className="md:col-span-2 space-y-4">
             <h2 className="text-xl font-bold text-[#2C2825] px-2">Respostas ({answers.length})</h2>
             
             {answers.map((ans, index) => (
                <Card key={ans.id} className="bg-white border-[#E5E0D8] rounded-2xl">
                   <CardContent className="p-6 space-y-3">
                      
                      <div className="flex items-start gap-3">
                         <span className="bg-[#FAF9F6] text-[#5C5855] text-xs font-bold px-2 py-1 rounded-md mt-0.5">
                            #{index + 1}
                         </span>
                         <h3 className="text-[#2C2825] font-bold text-lg leading-snug">
                            {ans.anamnese_questions?.question_text}
                         </h3>
                      </div>

                      <div className="pl-11">
                         <div className="bg-[#FAF9F6] border-[#E5E0D8] text-[#2C2825]">
                            {renderAnswerValue(ans.answer_value, ans.anamnese_questions?.type)}
                         </div>
                      </div>

                   </CardContent>
                </Card>
             ))}
          </div>
       </div>
    </div>
  );
}

function renderAnswerValue(value: any, type: string) {
  if (!value) return <span className="text-neutral-500 italic">Sem resposta</span>;

  if (Array.isArray(value)) {
    return (
      <ul className="list-disc list-inside space-y-1">
        {value.map((v: string, i: number) => (
          <li key={i}>{v}</li>
        ))}
      </ul>
    );
  }

  if (type === 'yes_no') {
     return value === 'true' || value === true ? 'Sim' : 'Não';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value); 
  }

  return <span>{String(value)}</span>;
}

'use client';

import { useState, useEffect } from 'react';
import { Button, Card, CardContent, Input, Badge } from '@projeto/ui';
import { Search, Eye, FileText, Calendar, User, Smartphone } from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { useProfile } from '@/providers/profile-provider';
import Link from 'next/link';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { toast } from 'sonner';

export default function AnamneseResponsesPage() {
  const { profile } = useProfile();
  const [responses, setResponses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (profile?.company_id) fetchResponses();
  }, [profile]);

  async function fetchResponses() {
    try {
      const supabase = createBrowserClient();
      const { data, error } = await supabase
        .from('anamnese_responses')
        .select(`
          *,
          anamnese_templates (name),
          clients (full_name, phone)
        `)
        .eq('company_id', profile?.company_id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setResponses(data || []);
    } catch (err) {
      console.error(err);
      toast.error('Erro ao carregar respostas');
    } finally {
      setLoading(false);
    }
  }

  const filteredResponses = responses.filter(r => 
    r.clients?.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.anamnese_templates?.name?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'completed_client':
        return <Badge className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20">Respondido pelo Cliente</Badge>;
      case 'completed_internal':
        return <Badge className="bg-blue-500/10 text-blue-500 border-blue-500/20">Preenchido Internamente</Badge>;
      default:
        return <Badge className="bg-yellow-500/10 text-yellow-500 border-yellow-500/20">Pendente</Badge>;
    }
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h1 className="text-3xl font-black text-[#2C2825] tracking-tight">Respostas de Anamnese</h1>
           <p className="text-[#8A847C] text-[10px] uppercase font-black tracking-widest mt-1">Gerencie as fichas preenchidas</p>
        </div>
        <div className="w-full md:w-72 relative">
           <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[#8A847C]" />
           <Input 
             placeholder="Buscar paciente ou ficha..." 
             className="pl-10 bg-[#020617] border-neutral-800 text-[#2C2825] rounded-xl"
             value={searchTerm}
             onChange={e => setSearchTerm(e.target.value)}
           />
        </div>
      </div>

      <div className="grid gap-4">
        {filteredResponses.map(r => (
          <Card key={r.id} className="bg-white border-[#E5E0D8] rounded-2xl hover:bg-[#0f172a]/50 transition-colors group">
            <CardContent className="p-4 flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
               <div className="flex items-center gap-4">
                  <div className="h-12 w-12 rounded-full bg-[#FAF9F6] text-[#8A847C]">
                     <User className="h-6 w-6" />
                  </div>
                  <div>
                     <h3 className="text-[#2C2825] font-bold text-lg">{r.clients?.full_name || 'Cliente Desconhecido'}</h3>
                     <div className="flex items-center gap-2 text-neutral-400 text-sm">
                        <FileText className="h-3 w-3" />
                        <span>{r.anamnese_templates?.name}</span>
                        <span className="text-neutral-600">•</span>
                        <Calendar className="h-3 w-3" />
                        <span>{format(new Date(r.created_at), "dd 'de' MMM, HH:mm", { locale: ptBR })}</span>
                     </div>
                  </div>
               </div>

               <div className="flex items-center gap-4 w-full md:w-auto mt-2 md:mt-0">
                  {getStatusBadge(r.status)}
                  
                  <Link href={`/dashboard/anamnese/responses/${r.id}`} className="ml-auto">
                     <Button variant="outline" size="sm" className="border-[#E5E0D8] text-[#5C5855] hover:text-[#2C2825] hover:bg-[#FAF9F6] rounded-lg">
                        <Eye className="mr-2 h-4 w-4" />
                        Ver Detalhes
                     </Button>
                  </Link>
               </div>
            </CardContent>
          </Card>
        ))}

        {filteredResponses.length === 0 && !loading && (
           <div className="text-center py-20 text-neutral-500 border border-dashed border-neutral-800 rounded-3xl">
              <FileText className="h-12 w-12 mx-auto mb-4 opacity-20" />
              <p>Nenhuma resposta encontrada.</p>
           </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { 
  Button, 
  Input, 
  TextArea, 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue, 
  Label, 
  Card 
} from '@projeto/ui';
import { Save, ArrowLeft, Trash2 } from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import QuestionEditor from '@/components/anamnese/question-editor';
import { toast } from 'sonner';
import Link from 'next/link';

export default function EditTemplatePage() {
  const router = useRouter();
  const params = useParams();
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [validityValue, setValidityValue] = useState<number>(6);
  const [validityUnit, setValidityUnit] = useState<'days' | 'months' | 'years'>('months');
  const [externalFormUrl, setExternalFormUrl] = useState('');
  const [questions, setQuestions] = useState<any[]>([]);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchTemplate();
  }, [params.id]);

  async function fetchTemplate() {
    try {
      const supabase = createBrowserClient();
      const { data, error } = await supabase
        .from('anamnese_templates')
        .select('*, anamnese_questions(*)')
        .eq('id', params.id)
        .single();

      if (error) throw error;
      
      setName(data.name);
      setDescription(data.description || '');
      setValidityValue(data.validity_value || 6);
      setValidityUnit(data.validity_unit || 'months');
      setExternalFormUrl(data.external_form_url || '');
      // Sort questions by order
      const sortedQuestions = (data.anamnese_questions || []).sort((a: any, b: any) => a.order - b.order);
      setQuestions(sortedQuestions);
    } catch (err) {
      console.error(err);
      toast.error('Erro ao carregar modelo');
      router.push('/dashboard/anamnese/templates');
    } finally {
      setLoading(false);
    }
  }

  async function handleSave() {
    if (!name) return toast.error('Nome do modelo é obrigatório');
    if (questions.length === 0) return toast.error('Adicione pelo menos uma pergunta');

    setSaving(true);
    try {
      const supabase = createBrowserClient();
      
      // 1. Atualizar Template
      const { error: tmplError } = await supabase
        .from('anamnese_templates')
        .update({
          name,
          description,
          validity_value: validityValue,
          validity_unit: validityUnit,
          external_form_url: externalFormUrl || null,
          updated_at: new Date().toISOString()
        })
        .eq('id', params.id);

      if (tmplError) throw tmplError;

      // 2. Upsert Perguntas
      const questionsToUpsert = questions.map((q: any, index: number) => ({
        id: q.id, 
        template_id: params.id,
        question_text: q.question_text,
        type: q.type,
        is_required: q.is_required,
        order: index + 1
      }));

      const { data: upsertedData, error: qError } = await supabase
        .from('anamnese_questions')
        .upsert(questionsToUpsert, { onConflict: 'id' })
        .select('id');

      if (qError) throw qError;

      // 3. Deletar perguntas removidas de forma segura
      const { data: existingQuestions } = await supabase
        .from('anamnese_questions')
        .select('id')
        .eq('template_id', params.id);
      
      const existingIds = existingQuestions?.map((q: any) => q.id) || [];
      const currentIds = questions.map(q => q.id);
      const toDelete = existingIds.filter(id => !currentIds.includes(id));

      if (toDelete.length > 0) {
        const { error: delError } = await supabase
          .from('anamnese_questions')
          .delete()
          .in('id', toDelete);
        
        if (delError) throw delError;
      }
      
      // Let's refine delete logic in code below to be safe.

      toast.success('Modelo atualizado!');
      router.push('/dashboard/anamnese/templates');
    } catch (err: any) {
      console.error(err);
      toast.error('Erro ao salvar: ' + err.message);
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete() {
    if (!confirm('Tem certeza? Isso apagará todas as respostas vinculadas.')) return;
    
    setSaving(true);
    try {
        const supabase = createBrowserClient();
        const { error } = await supabase.from('anamnese_templates').delete().eq('id', params.id);
        if (error) throw error;
        toast.success('Modelo excluído');
        router.push('/dashboard/anamnese/templates');
    } catch(err: any) {
        toast.error('Erro ao excluir: ' + err.message);
        setSaving(false);
    }
  }

  if (loading) return <div>Carregando...</div>;

  return (
    <div className="space-y-6 max-w-4xl mx-auto pb-20">
       <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Link href="/dashboard/anamnese/templates">
                <Button variant="ghost" size="icon" className="text-[#2C2825] hover:bg-[#5C5855] rounded-xl">
                    <ArrowLeft className="h-5 w-5" />
                </Button>
            </Link>
            <div>
                <h1 className="text-2xl font-black text-[#2C2825]">Editar Modelo</h1>
                <p className="text-[#8A847C] text-sm">Atualize as perguntas e descrições.</p>
            </div>
          </div>
          <Button 
            variant="ghost" 
            onClick={handleDelete}
            className="text-red-500 hover:bg-red-500/10 hover:text-red-400 font-bold rounded-xl"
          >
             <Trash2 className="mr-2 h-4 w-4" />
             Excluir
          </Button>
       </div>

       <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="space-y-6">
             <Card className="bg-white border-[#E5E0D8] rounded-3xl p-6">
                <div className="space-y-4">
                   <div className="space-y-2">
                      <Label className="text-[#5C5855] font-bold">Nome do Modelo</Label>
                      <Input 
                        value={name} 
                        onChange={e => setName(e.target.value)} 
                        className="bg-[#FAF9F6] border-[#E5E0D8] text-[#2C2825] h-12 rounded-xl"
                      />
                   </div>
                   <div className="space-y-2">
                      <Label className="text-[#5C5855] font-bold">Descrição</Label>
                        <TextArea 
                        value={description} 
                        onChange={e => setDescription(e.target.value)} 
                        className="bg-[#FAF9F6] border-[#E5E0D8] text-[#2C2825] min-h-[100px] rounded-xl"
                      />
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                         <Label className="text-[#5C5855] font-bold">Validade</Label>
                         <Input 
                           type="number"
                           value={validityValue}
                           onChange={e => setValidityValue(Number(e.target.value))}
                           className="bg-[#FAF9F6] border-[#E5E0D8] text-[#2C2825] h-12 rounded-xl"
                         />
                      </div>
                      <div className="space-y-2">
                         <Label className="text-[#5C5855] font-bold">Unidade</Label>
                         <Select 
                           value={validityUnit} 
                           onValueChange={(v: any) => setValidityUnit(v)} 
                         >
                             <SelectTrigger className="bg-[#FAF9F6] border-[#E5E0D8] text-[#2C2825] h-12 rounded-xl">
                                <SelectValue placeholder="Unidade" />
                             </SelectTrigger>
                             <SelectContent>
                                <SelectItem value="days">Dias</SelectItem>
                                <SelectItem value="months">Meses</SelectItem>
                                <SelectItem value="years">Anos</SelectItem>
                             </SelectContent>
                         </Select>
                      </div>
                   </div>
                   <div className="space-y-2">
                      <Label className="text-[#5C5855] font-bold text-sm">Formulário Externo (Google Forms) Opcional</Label>
                      <p className="text-xs text-[#8A847C] mb-1">Se preenchido, os pacientes serão redirecionados para este link.</p>
                      <Input 
                        value={externalFormUrl} 
                        onChange={e => setExternalFormUrl(e.target.value)} 
                        placeholder="https://docs.google.com/forms/..."
                        className="bg-[#FAF9F6] border-[#E5E0D8] text-[#2C2825] h-12 rounded-xl"
                      />
                   </div>
                </div>
             </Card>

             <Button 
               onClick={handleSave} 
               className="w-full bg-primary-500 hover:bg-primary-600 text-[#2C2825] font-bold h-14 rounded-2xl text-lg shadow-lg shadow-primary-500/20"
               loading={saving}
             >
                <Save className="mr-2 h-5 w-5" />
                Salvar Alterações
             </Button>
          </div>

          <div className="lg:col-span-2 space-y-4">
             <div className="flex items-center justify-between">
                <h2 className="text-xl font-bold text-[#2C2825]">Perguntas</h2>
                <span className="text-[#2C2825] bg-neutral-100 px-3 py-1 rounded-full">{questions.length}</span>
             </div>
             
             <QuestionEditor questions={questions} onChange={setQuestions} />
          </div>
       </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Button, Card, CardContent, Input, Label, Badge } from '@projeto/ui';
import { Plus, Edit, Trash2, FileText, CheckCircle2 } from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { useProfile } from '@/providers/profile-provider';
import Link from 'next/link';
import { toast } from 'sonner';

export default function AnamneseTemplatesPage() {
  const { profile } = useProfile();
  const [templates, setTemplates] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (profile?.company_id) fetchTemplates();
  }, [profile]);

  async function fetchTemplates() {
    try {
      const supabase = createBrowserClient();
      const { data, error } = await supabase
        .from('anamnese_templates')
        .select('*')
        .eq('company_id', profile?.company_id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setTemplates(data || []);
    } catch (err) {
      console.error(err);
      toast.error('Erro ao carregar modelos');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
           <h1 className="text-3xl font-black text-[#2C2825] tracking-tight">Modelos de Anamnese</h1>
           <p className="text-[#8A847C] text-[10px] uppercase font-black tracking-widest mt-1">Configure as fichas dos seus pacientes</p>
        </div>
        <Link href="/dashboard/anamnese/templates/new">
           <Button className="bg-primary-500 hover:bg-primary-600 font-bold rounded-xl h-11 px-6">
              <Plus className="mr-2 h-4 w-4" />
              Novo Modelo
           </Button>
        </Link>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {templates.map(t => (
          <Card key={t.id} className="bg-white border-[#E5E0D8] rounded-3xl backdrop-blur-sm group hover:border-primary-500/50 transition-all">
            <CardContent className="p-6 space-y-4">
               <div className="flex items-start justify-between">
                  <div className="bg-primary-500/10 p-3 rounded-2xl text-primary-500">
                     <FileText className="h-6 w-6" />
                  </div>
                  {t.is_active && (
                     <Badge className="bg-emerald-500/10 text-emerald-500 border-none px-2 py-0.5">Ativo</Badge>
                  )}
               </div>
               
               <div>
                  <h3 className="text-[#2C2825] font-bold text-lg">{t.name}</h3>
                  <p className="text-[#5C5855] text-sm line-clamp-2 mt-1">{t.description || 'Sem descrição'}</p>
               </div>

               <div className="flex items-center gap-2 pt-2">
                  <Link href={`/dashboard/anamnese/templates/${t.id}`} className="flex-1">
                     <Button variant="outline" className="w-full border-neutral-800 hover:bg-primary-500 hover:text-[#2C2825] rounded-xl">
                        <Edit className="mr-2 h-4 w-4" />
                        Editar
                     </Button>
                  </Link>
               </div>
            </CardContent>
          </Card>
        ))}

        {templates.length === 0 && !loading && (
           <div className="col-span-full text-center py-20 text-neutral-500">
              <p>Nenhum modelo criado. Crie o primeiro para começar.</p>
           </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { createBrowserClient } from '@/lib/supabase-browser';
import { 
  Button, 
  Input, 
  Card, 
  CardContent, 
