} from 'lucide-react';
import Link from 'next/link';

export default function EditClientPage({ params }: { params: { id: string } }) {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [formData, setFormData] = useState({
    full_name: '',
    phone: '',
    email: '',
    cpf: '',
    gender: '',
    birth_date: '',
    instagram: '',
    address_street: '',
    address_number: '',
    address_neighborhood: '',
    address_city: '',
    address_state: '',
    address_zip_code: '',
    emergency_contact_name: '',
    emergency_contact_phone: '',
    observations: ''
  });

  useEffect(() => {
    fetchClient();
  }, [params.id]);

  async function fetchClient() {
    try {
      const supabase = createBrowserClient();
      const { data: client, error: fetchError } = await supabase
        .from('clients')
        .select('*')
        .eq('id', params.id)
        .single();

      if (fetchError) throw fetchError;
      if (client) {
        setFormData({
          full_name: client.full_name || '',
          phone: client.phone || '',
          email: client.email || '',
          cpf: client.cpf || '',
          gender: client.gender || '',
          birth_date: client.birth_date || '',
          instagram: client.instagram || '',
          address_street: client.address_street || '',
          address_number: client.address_number || '',
          address_neighborhood: client.address_neighborhood || '',
          address_city: client.address_city || '',
          address_state: client.address_state || '',
          address_zip_code: client.address_zip_code || '',
          emergency_contact_name: client.emergency_contact_name || '',
          emergency_contact_phone: client.emergency_contact_phone || '',
          observations: client.observations || ''
        });
      }
    } catch (err: any) {
      console.error('Error fetching client:', err);
      setError('Erro ao carregar dados do cliente.');
    } finally {
      setLoading(false);
    }
  }

  const handleChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setError('');

    try {
      const supabase = createBrowserClient();

      // Preparar dados (tratar strings vazias como null para evitar erros de UNIQUE ou obrigatoriedade)
      const sanitizedData = Object.fromEntries(
        Object.entries(formData).map(([key, value]) => [
          key, 
          value === '' ? null : value
        ])
      );

      const { error: updateError } = await supabase
        .from('clients')
        .update(sanitizedData)
        .eq('id', params.id);

      if (updateError) throw updateError;

      router.push(`/dashboard/clients/${params.id}`);
      router.refresh();
      router.push('/dashboard/clients'); // Redirect to list after edit
    } catch (err: any) {
      console.error('Error updating client:', err);
      setError(err.message || 'Erro ao salvar alterações. Tente novamente.');
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="h-[60vh] flex flex-col items-center justify-center gap-4">
        <Loader2 className="h-10 w-10 text-emerald-500 animate-spin" />
        <p className="text-neutral-500 font-bold uppercase text-[10px] tracking-widest">Carregando Perfil...</p>
      </div>
    );
