                     </div>
                     <div className="space-y-2">
                        <label className="text-xs font-bold text-neutral-500 uppercase ml-1">Nº</label>
                        <Input 
                           placeholder="123" 
                           className="bg-[#020617] border-neutral-800 h-11 rounded-xl text-white placeholder:text-neutral-700"
