import { 
  Button, 
  Card, 
  CardContent, 
  CardHeader, 
  CardTitle,
  Input,
  Badge,
  toast,
  cn
} from '@projeto/ui';
import { 
  Target, 
  Trophy, 
  TrendingUp, 
  Calendar, 
  Activity, 
  Package, 
  TrendingDown,
  Plus,
  ArrowUpRight,
  ArrowDownRight,
  ChevronRight,
  ChevronLeft,
  LayoutDashboard
} from 'lucide-react';
import { useProfile } from '@/providers/profile-provider';
import { 
  format, 
  startOfDay, 
  endOfDay, 
  startOfMonth, 
  endOfMonth, 
  startOfYear, 
  endOfYear,
  isWithinInterval,
  addMonths,
  subMonths
} from 'date-fns';
import { ptBR } from 'date-fns/locale';

type GoalCategory = 'revenue' | 'appointments' | 'procedures' | 'products';
type GoalPeriod = 'daily' | 'monthly' | 'yearly';

export default function PlanningPage() {
  const { profile } = useProfile();
  const [mounted, setMounted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [goals, setGoals] = useState<any[]>([]);
  const [actuals, setActuals] = useState({
    revenue: 0,
    appointments: 0,
    procedures: 0,
    products: 0
  });

  const [isEditing, setIsEditing] = useState(false);
  const [editingGoals, setEditingGoals] = useState<any[]>([]);

  useEffect(() => {
    setMounted(true);
    setCurrentDate(new Date());
  }, []);

  useEffect(() => {
    if (mounted && profile?.company_id) {
      fetchData();
    }
  }, [profile, currentDate, mounted]);

  async function fetchData() {
    setLoading(true);
    try {
      const supabase = createBrowserClient();

      const monthStart = startOfMonth(currentDate);
      const monthEnd = endOfMonth(currentDate);

      // Fetch Goals
      const { data: goalsData, error: goalsError } = await supabase
        .from('strategic_goals')
        .select('*')
        .eq('company_id', profile?.company_id)
        .eq('period', 'monthly')
        .gte('target_date', format(monthStart, 'yyyy-MM-dd'))
        .lte('target_date', format(monthEnd, 'yyyy-MM-dd'));

      if (goalsError) {
        console.error('Error fetching goals:', goalsError);
        // If table doesn't exist, we might get an error. Don't throw, just log.
      }

      setGoals(goalsData || []);

      // Fetch Actual Transactions for Revenue
      const { data: transRes } = await supabase
        .from('transactions')
        .select('amount')
        .eq('company_id', profile?.company_id)
        .eq('type', 'income')
        .eq('status', 'completed')
        .gte('date', format(monthStart, 'yyyy-MM-dd'))
        .lte('date', format(monthEnd, 'yyyy-MM-dd'));

      // Fetch Appointments
      const { data: appsRes } = await supabase
        .from('appointments')
        .select('*, procedures(id)')
        .eq('company_id', profile?.company_id)
        .eq('status', 'completed')
        .gte('start_time', monthStart.toISOString())
        .lte('start_time', monthEnd.toISOString());

      // Fetch Product Sales (Inventory Trans)
      const { data: invRes } = await supabase
        .from('inventory_transactions')
        .select('quantity')
        .eq('company_id', profile?.company_id)
        .eq('type', 'out')
        .gte('created_at', monthStart.toISOString())
        .lte('created_at', monthEnd.toISOString());

      const revenue = transRes?.reduce((sum, t) => sum + Number(t.amount), 0) || 0;
      const appointments = appsRes?.length || 0;
      const procedures = appsRes?.reduce((sum, a) => sum + (Array.isArray(a.procedures) ? a.procedures.length : a.procedures ? 1 : 0), 0) || 0;
      const products = invRes?.reduce((sum, i) => sum + Number(i.quantity), 0) || 0;

      setActuals({ revenue, appointments, procedures, products });
    } catch (err: any) {
      console.error('Error fetching planning data:', err);
      toast.error('Erro ao carregar dados de planejamento');
    } finally {
      setLoading(false);
    }
  }

  if (!mounted) return null;

  const getGoalValue = (category: GoalCategory) => {
    return goals.find(g => g.category === category)?.target_value || 0;
  };

  const calculateProgress = (actual: number, target: number) => {
    if (!target) return 0;
    return Math.min(Math.round((actual / target) * 100), 100);
  };

  async function handleSaveGoals() {
    setLoading(true);
    try {
      const supabase = createBrowserClient();
      const monthStart = startOfMonth(currentDate);

      const categories: GoalCategory[] = ['revenue', 'appointments', 'procedures', 'products'];

      const upsertData = categories.map(cat => ({
        company_id: profile?.company_id,
        category: cat,
        period: 'monthly',
        target_value: editingGoals.find(eg => eg.category === cat)?.target_value || 0,
        target_date: format(monthStart, 'yyyy-MM-dd')
      }));

      // In Supabase, unique constraint (company_id, category, period, target_date) handles conflict
      const { error } = await supabase
        .from('strategic_goals')
        .upsert(upsertData, { 
          onConflict: 'company_id, category, period, target_date' 
        });

      if (error) throw error;

      toast.success('Metas atualizadas com sucesso!');
      setIsEditing(false);
      fetchData();
    } catch (err) {
      console.error('Error saving goals:', err);
      toast.error('Erro ao salvar metas');
    } finally {
      setLoading(false);
    }
  }

  function startEditing() {
    const categories: GoalCategory[] = ['revenue', 'appointments', 'procedures', 'products'];
    const currentEditing = categories.map(cat => ({
      category: cat,
      target_value: getGoalValue(cat)
    }));
    setEditingGoals(currentEditing);
    setIsEditing(true);
  }

  return (
    <div className="space-y-8 animate-fade-in pb-16">
      {/* Header */}
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-amber-950 rounded-2xl shadow-xl shadow-amber-900/10 border border-amber-900/50">
            <Trophy className="h-8 w-8 text-amber-500" />
          </div>
          <div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tight font-serif uppercase">Melhor Planejamento</h1>
            <p className="text-slate-500 text-sm font-medium">Defina metas estratégicas e acompanhe o crescimento da sua clínica.</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm">
             <Button 
                variant="ghost" 
                size="icon" 
                className="h-10 w-10 rounded-xl"
                onClick={() => setCurrentDate(subMonths(currentDate, 1))}
             >
                <ChevronLeft className="h-5 w-5" />
             </Button>
             <span className="px-4 text-sm font-black text-slate-900 uppercase tracking-widest min-w-[140px] text-center">
                {format(currentDate, 'MMMM yyyy', { locale: ptBR })}
             </span>
             <Button 
                variant="ghost" 
                size="icon" 
                className="h-10 w-10 rounded-xl"
                onClick={() => setCurrentDate(addMonths(currentDate, 1))}
             >
                <ChevronRight className="h-5 w-5" />
             </Button>
          </div>

          <Button 
             onClick={isEditing ? handleSaveGoals : startEditing}
             className={cn(
               "h-12 px-8 rounded-2xl shadow-xl font-black transition-all active:scale-95",
               isEditing ? "bg-emerald-600 hover:bg-emerald-700 text-white shadow-emerald-200" : "bg-slate-900 hover:bg-black text-white shadow-slate-200"
             )}
          >
             {isEditing ? 'Salvar Planejamento' : 'Ajustar Metas'}
          </Button>
        </div>
      </div>

      {/* Main Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <PlanningCard 
          title="Faturamento" 
          actual={actuals.revenue} 
          target={isEditing ? Number(editingGoals.find(g => g.category === 'revenue')?.target_value || 0) : getGoalValue('revenue')}
          icon={TrendingUp}
          color="emerald"
          isCurrency
          isEditing={isEditing}
          onEdit={(val: number) => setEditingGoals(prev => prev.map(g => g.category === 'revenue' ? { ...g, target_value: val } : g))}
        />
        <PlanningCard 
          title="Atendimentos" 
          actual={actuals.appointments} 
          target={isEditing ? Number(editingGoals.find(g => g.category === 'appointments')?.target_value || 0) : getGoalValue('appointments')}
          icon={Calendar}
          color="blue"
          isEditing={isEditing}
          onEdit={(val: number) => setEditingGoals(prev => prev.map(g => g.category === 'appointments' ? { ...g, target_value: val } : g))}
        />
        <PlanningCard 
          title="Procedimentos" 
          actual={actuals.procedures} 
          target={isEditing ? Number(editingGoals.find(g => g.category === 'procedures')?.target_value || 0) : getGoalValue('procedures')}
          icon={Activity}
          color="rose"
          isEditing={isEditing}
          onEdit={(val: number) => setEditingGoals(prev => prev.map(g => g.category === 'procedures' ? { ...g, target_value: val } : g))}
        />
        <PlanningCard 
          title="Venda de Produtos" 
          actual={actuals.products} 
          target={isEditing ? Number(editingGoals.find(g => g.category === 'products')?.target_value || 0) : getGoalValue('products')}
          icon={Package}
          color="amber"
          isEditing={isEditing}
          onEdit={(val: number) => setEditingGoals(prev => prev.map(g => g.category === 'products' ? { ...g, target_value: val } : g))}
        />
      </div>

      {/* Analysis Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         <Card className="lg:col-span-2 bg-white border-slate-100 rounded-3xl shadow-xl shadow-slate-200/50 overflow-hidden">
            <CardHeader className="p-8 border-b border-slate-50">
               <CardTitle className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-3">
                  <LayoutDashboard className="h-6 w-6 text-slate-400" />
                  Visão Geral do Desempenho
               </CardTitle>
            </CardHeader>
            <CardContent className="p-8 space-y-10">
               <GoalProgress 
                  label="Meta de Faturamento" 
                  actual={actuals.revenue} 
                  target={getGoalValue('revenue')} 
                  color="bg-emerald-500" 
                  isCurrency 
               />
               <GoalProgress 
                  label="Meta de Atendimentos" 
                  actual={actuals.appointments} 
                  target={getGoalValue('appointments')} 
                  color="bg-blue-500" 
               />
               <GoalProgress 
                  label="Meta de Procedimentos" 
                  actual={actuals.procedures} 
                  target={getGoalValue('procedures')} 
                  color="bg-rose-500" 
               />
               <GoalProgress 
                  label="Meta de Produtos" 
                  actual={actuals.products} 
                  target={getGoalValue('products')} 
                  color="bg-amber-500" 
               />
            </CardContent>
         </Card>

         <Card className="bg-slate-900 text-white border-none rounded-3xl shadow-xl shadow-slate-900/20 p-8 flex flex-col justify-between relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/10 rounded-full blur-[80px] -mr-32 -mt-32" />

            <div className="relative z-10 space-y-6">
               <Badge className="bg-amber-500 hover:bg-amber-600 text-amber-950 font-black px-4 py-1.5 rounded-full uppercase text-[10px]">Estratégia</Badge>
               <h3 className="text-2xl font-black italic tracking-tight font-serif">Como atingir suas metas mais rápido?</h3>
               <p className="text-slate-400 text-sm leading-relaxed">
                  Baseado no seu desempenho atual, você atingiu <span className="text-white font-bold">{calculateProgress(actuals.revenue, getGoalValue('revenue'))}%</span> da sua meta de faturamento. 
                  Para bater a meta total, sugerimos focar no ticket médio dos próximos atendimentos.
               </p>
            </div>

            <div className="mt-12 space-y-4 relative z-10">
               <div className="bg-white/5 rounded-2xl p-4 border border-white/10">
                  <p className="text-[10px] font-black text-amber-500 uppercase tracking-widest mb-1">Dica do sistema</p>
                  <p className="text-xs text-slate-300 italic">"Clínicas com metas mensais claras crescem até 40% mais rápido que a média."</p>
               </div>
               <Button className="w-full h-12 bg-white text-slate-900 font-black rounded-xl hover:bg-slate-100 transition-all uppercase tracking-widest text-xs">
                  Ver Relatórios Completos
               </Button>
            </div>
         </Card>
      </div>
    </div>
  );
}

function PlanningCard({ title, actual, target, icon: Icon, color, isCurrency, isEditing, onEdit }: any) {
  const progress = target > 0 ? Math.min(Math.round((actual / target) * 100), 100) : 0;

  const colors = {
    emerald: 'bg-emerald-50 text-emerald-600 border-emerald-100 progress-bg-emerald-500',
    blue: 'bg-blue-50 text-blue-600 border-blue-100 progress-bg-blue-500',
    rose: 'bg-rose-50 text-rose-600 border-rose-100 progress-bg-rose-500',
    amber: 'bg-amber-50 text-amber-600 border-amber-100 progress-bg-amber-500'
  };

  const progressColors = {
    emerald: 'bg-emerald-500',
    blue: 'bg-blue-500',
    rose: 'bg-rose-500',
    amber: 'bg-amber-500'
  };

  const formatValue = (val: number) => {
    if (isCurrency) {
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
    }
    return val.toLocaleString();
  };

  return (
    <Card className="bg-white border-slate-100 rounded-3xl shadow-xl shadow-slate-200/50 p-6 group hover:border-[#D4AF37]/20 transition-all overflow-hidden relative">
      <div className="flex items-center justify-between mb-6">
        <div className={cn("p-2.5 rounded-2xl border", colors[color as keyof typeof colors].split(' ').slice(0, 3).join(' '))}>
          <Icon className="h-5 w-5" />
        </div>
        <div className="text-right">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">{title}</p>
           <p className="text-lg font-black text-slate-900 italic">{progress}%</p>
        </div>
      </div>

      <div className="space-y-4">
         <div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Realizado</p>
            <h4 className="text-xl font-black text-slate-950">{formatValue(actual)}</h4>
         </div>

         <div className="h-px bg-slate-50 w-full" />

         <div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Meta</p>
            {isEditing ? (
              <div className="relative">
                 {isCurrency && <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold text-sm">R$</span>}
                 <Input 
                   type="number" 
                   value={target} 
                   onChange={(e) => onEdit(Number(e.target.value))}
                   className={cn(
                     "h-10 bg-slate-50 border-slate-200 rounded-xl font-black text-slate-900",
                     isCurrency ? "pl-9" : ""
                   )}
                 />
              </div>
            ) : (
              <h4 className="text-xl font-black text-slate-300 italic">{formatValue(target)}</h4>
            )}
         </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 h-1 bg-slate-50">
         <div 
           className={cn("h-full transition-all duration-1000", progressColors[color as keyof typeof progressColors])} 
           style={{ width: `${progress}%` }}
         />
      </div>
    </Card>
  );
}

function GoalProgress({ label, actual, target, color, isCurrency }: any) {
  const progress = target > 0 ? Math.min(Math.round((actual / target) * 100), 100) : 0;

  const formatValue = (val: number) => {
    if (isCurrency) {
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
    }
    return val.toLocaleString();
  };

  return (
    <div className="space-y-3 group">
       <div className="flex items-center justify-between">
          <div className="flex flex-col">
             <p className="text-xs font-black text-slate-900 uppercase tracking-wider">{label}</p>
             <p className="text-[10px] text-slate-400 font-medium">Restam {formatValue(Math.max(0, target - actual))} para a meta</p>
          </div>
          <div className="text-right">
             <span className="text-sm font-black text-slate-950">{formatValue(actual)}</span>
             <span className="text-xs text-slate-300 font-bold mx-2">/</span>
             <span className="text-xs text-slate-400 font-bold">{formatValue(target)}</span>
          </div>
       </div>
       <div className="h-3 w-full bg-slate-50 rounded-full border border-slate-100 overflow-hidden relative shadow-inner">
          <div 
             className={cn("h-full rounded-full transition-all duration-1000 group-hover:brightness-110 shadow-lg", color)}
             style={{ width: `${progress}%` }}
          >
             <div className="w-full h-full opacity-30 bg-gradient-to-r from-transparent via-white/50 to-transparent animate-shimmer" />
          </div>
       </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { 
  Card, 
  CardHeader, 
  CardTitle, 
  CardContent, 
  Button, 
  Input, 
  Badge,
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
  cn,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
  Label
} from '@projeto/ui';
import { 
  Activity,
  Trash2, 
  Edit3, 
  Plus,
  Info
} from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { useProfile } from '@/providers/profile-provider';

export default function ProceduresClient() {
  const [procedures, setProcedures] = useState<any[]>([]);
  const [templates, setTemplates] = useState<any[]>([]); 
  const [loading, setLoading] = useState(true);
  const [isAddingProcedure, setIsAddingProcedure] = useState(false);

  const [newService, setNewService] = useState({
    name: '',
    duration_minutes: 60,
    price: 0,
    maintenance_required: false,
    maintenance_days_limit: 30,
    maintenance_period_unit: 'days', // 'days', 'weeks', 'months'
    maintenance_duration_minutes: 60,
    requires_anamnese: false,
    anamnese_template_id: ''
  });

  const supabase = createBrowserClient();
  const { profile } = useProfile();
  const companyId = profile?.company_id;

  const fetchProcedures = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('procedures')
        .select('*')
        .eq('company_id', companyId)
        .order('name');

      if (error) throw error;
      if (data) setProcedures(data);

      const { data: tmplData } = await supabase
        .from('anamnese_templates')
        .select('id, name')
        .eq('company_id', companyId)
        .eq('is_active', true);

      if (tmplData) setTemplates(tmplData);
    } catch (err: any) {
      if (err.message?.includes('AbortError') || err.name === 'AbortError') return;
      console.error('Error fetching settings:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (companyId) {
      fetchProcedures();
    }
  }, [companyId]);

  const handleCreateService = async () => {
    const { error } = await supabase
      .from('procedures')
      .insert([{
        ...newService,
        company_id: companyId
      }]);

    if (!error) {
      setIsAddingProcedure(false);
      setNewService({
        name: '',
        duration_minutes: 60,
        price: 0,
        maintenance_required: false,
        maintenance_days_limit: 30,
        maintenance_period_unit: 'days',
        maintenance_duration_minutes: 60,
        requires_anamnese: false,
        anamnese_template_id: ''
      });
      fetchProcedures();
    } else {
      console.error('Error creating service:', JSON.stringify(error, null, 2));
      alert(`Erro ao criar serviço: ${error.message || 'Verifique as permissões'}`);
    }
  };

  const handleDeleteService = async (id: string) => {
    if (!companyId) return;
    const { error } = await supabase
      .from('procedures')
      .delete()
      .eq('id', id)
      .eq('company_id', companyId); 

    if (!error) {
      fetchProcedures();
    }
  };


  return (
    <div className="space-y-10 animate-fade-in pb-20">
      <div className="flex flex-col gap-6 md:flex-row md:items-end justify-between">
        <div className="flex items-center gap-6">
          <div className="p-3 bg-[#D4AF37]/10 rounded-2xl">
            <Activity className="h-6 w-6 text-[#D4AF37]" />
          </div>
          <div>
            <h1 className="text-3xl font-black text-[#2C2825] tracking-tight">Procedimentos</h1>
            <p className="text-[#8A847C] text-[10px] uppercase font-black tracking-widest mt-1">Gerencie seu catálogo de serviços</p>
          </div>
        </div>

        <Dialog open={isAddingProcedure} onOpenChange={setIsAddingProcedure}>
           <DialogTrigger asChild>
             <Button className="h-11 px-6 bg-[#D4AF37] text-white hover:bg-[#B5952F] font-black rounded-xl active:scale-[0.98] transition-all">
                 <Plus className="h-5 w-5 mr-2" />
                 Novo Serviço
             </Button>
           </DialogTrigger>
           <DialogContent className="bg-white border-[#E5E0D8] text-[#2C2825] rounded-3xl max-w-md">
             <DialogHeader>
               <DialogTitle className="text-xl font-bold flex items-center gap-2">
                 <Plus className="h-5 w-5 text-[#D4AF37]" />
                 Novo Procedimento
               </DialogTitle>
             </DialogHeader>

             <div className="space-y-6 py-4">
               <div className="space-y-2">
                 <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Nome do Serviço</Label>
                 <Input 
                   placeholder="Ex: Limpeza de Pele" 
                   value={newService.name}
                   onChange={(e) => setNewService({...newService, name: e.target.value})}
                   className="bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold" 
                 />
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-2">
                   <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Duração</Label>
                   <div className="flex gap-2">
                     <div className="relative flex-1">
                       <Input 
                         type="number"
                         min="0"
                         placeholder="0"
                         value={Math.floor(newService.duration_minutes / 60).toString()}
                         onChange={(e) => {
                           const h = parseInt(e.target.value) || 0;
                           const m = newService.duration_minutes % 60;
                           setNewService({...newService, duration_minutes: (h * 60) + m});
                         }}
                         className="bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold pr-8" 
                       />
                       <span className="absolute right-3 top-3.5 text-xs text-[#8A847C] font-bold">H</span>
                     </div>
                     <div className="relative flex-1">
                       <Input 
                         type="number"
                         min="0"
                         max="59"
                         placeholder="0"
                         value={(newService.duration_minutes % 60).toString()}
                         onChange={(e) => {
                           let m = parseInt(e.target.value) || 0;
                           if (m > 59) m = 59;
                           const h = Math.floor(newService.duration_minutes / 60);
                           setNewService({...newService, duration_minutes: (h * 60) + m});
                         }}
                         className="bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold pr-10" 
                       />
                       <span className="absolute right-3 top-3.5 text-xs text-[#8A847C] font-bold">MIN</span>
                     </div>
                   </div>
                 </div>
                 <div className="space-y-2">
                   <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Valor (R$)</Label>
                   <Input 
                     type="number"
                     step="0.01"
                     value={newService.price}
                     onChange={(e) => setNewService({...newService, price: parseFloat(e.target.value) || 0})}
                     className="bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold" 
                   />
                 </div>
               </div>

               <div className="flex items-center gap-3 p-4 bg-[#FDFBF7] rounded-2xl border border-[#E5E0D8]">
                 <input 
                   type="checkbox" 
                   id="maintenance"
                   checked={newService.maintenance_required}
                   onChange={(e) => setNewService({...newService, maintenance_required: e.target.checked})}
                   className="w-5 h-5 rounded border-[#E5E0D8] bg-white text-[#D4AF37] focus:ring-[#D4AF37]"
                 />
                 <div className="flex-1">
                   <Label htmlFor="maintenance" className="text-sm font-bold block">Requer Manutenção</Label>
                   <p className="text-[10px] text-[#8A847C]">Ativa lembretes automáticos na agenda.</p>
                 </div>
               </div>

               {newService.maintenance_required && (
                 <div className="space-y-4 animate-in slide-in-from-top-2 duration-200">
                   <div className="grid grid-cols-2 gap-4">
                     <div className="space-y-2">
                       <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Prazo de Manutenção</Label>
                       <Input 
                         type="number"
                         value={newService.maintenance_days_limit}
                         onChange={(e) => setNewService({...newService, maintenance_days_limit: parseInt(e.target.value) || 0})}
                         className="bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold" 
                       />
                     </div>
                     <div className="space-y-2">
                       <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Unidade de Tempo</Label>
                       <select 
                         value={newService.maintenance_period_unit}
                         onChange={(e) => setNewService({...newService, maintenance_period_unit: e.target.value})}
                         className="w-full bg-[#FDFBF7] border border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold px-4"
                       >
                          <option value="days">Dias</option>
                          <option value="months">Meses</option>
                       </select>
                     </div>
                   </div>

                   <div className="space-y-2">
                     <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Duração da Manutenção</Label>
                     <div className="flex gap-2">
                       <div className="relative flex-1">
                         <Input 
                           type="number"
                           min="0"
                           placeholder="0"
                           value={Math.floor(newService.maintenance_duration_minutes / 60).toString()}
                           onChange={(e) => {
                             const h = parseInt(e.target.value) || 0;
                             const m = newService.maintenance_duration_minutes % 60;
                             setNewService({...newService, maintenance_duration_minutes: (h * 60) + m});
                           }}
                           className="bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold pr-8" 
                         />
                         <span className="absolute right-3 top-3.5 text-xs text-[#8A847C] font-bold">H</span>
                       </div>
                       <div className="relative flex-1">
                         <Input 
                           type="number"
                           min="0"
                           max="59"
                           placeholder="0"
                           value={(newService.maintenance_duration_minutes % 60).toString()}
                           onChange={(e) => {
                             let m = parseInt(e.target.value) || 0;
                             if (m > 59) m = 59;
                             const h = Math.floor(newService.maintenance_duration_minutes / 60);
                             setNewService({...newService, maintenance_duration_minutes: (h * 60) + m});
                           }}
                           className="bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold pr-10" 
                         />
                         <span className="absolute right-3 top-3.5 text-xs text-[#8A847C] font-bold">MIN</span>
                       </div>
                     </div>
                   </div>
                 </div>
               )}
             </div>

             {/* Anamnese Configuration */}
             <div className="space-y-2 pt-4 border-t border-[#E5E0D8]">
                <div className="flex items-center gap-3 p-4 bg-[#FDFBF7] rounded-2xl border border-[#E5E0D8]">
                   <input 
                     type="checkbox" 
                     id="anamnese"
                     checked={newService.requires_anamnese}
                     onChange={(e) => setNewService({...newService, requires_anamnese: e.target.checked})}
                     className="w-5 h-5 rounded border-[#E5E0D8] bg-white text-[#D4AF37] focus:ring-[#D4AF37]"
                   />
                   <div className="flex-1">
                     <Label htmlFor="anamnese" className="text-sm font-bold block">Exige Anamnese</Label>
                     <p className="text-[10px] text-[#8A847C]">Obrigatório preenchimento de ficha antes de finalizar.</p>
                   </div>
                </div>

                {newService.requires_anamnese && (
                   <div className="space-y-2 animate-in slide-in-from-top-2 duration-200">
                      <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Modelo de Ficha</Label>
                      <select 
                        value={newService.anamnese_template_id}
                        onChange={(e) => setNewService({...newService, anamnese_template_id: e.target.value})}
                        className="w-full bg-[#FDFBF7] border border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold px-4"
                      >
                         <option value="">Selecione um modelo...</option>
                         {templates.map(t => (
                            <option key={t.id} value={t.id}>{t.name}</option>
                         ))}
                      </select>
                   </div>
                )}
             </div>

             <DialogFooter className="gap-3">
               <Button variant="ghost" onClick={() => setIsAddingProcedure(false)} className="text-[#5C5855] hover:text-[#2C2825] font-bold">Cancelar</Button>
               <Button onClick={handleCreateService} className="bg-[#D4AF37] hover:bg-[#B5952F] text-white font-bold px-8">Cadastrar Serviço</Button>
             </DialogFooter>
           </DialogContent>
        </Dialog>
      </div>

      <div className="space-y-6">
        <Card className="bg-white border-[#E5E0D8] rounded-3xl overflow-hidden shadow-sm">
           <Table>
              <TableHeader className="bg-[#FAF6E9] border-b border-[#E5E0D8]">
                 <TableRow className="hover:bg-transparent border-none">
                    <TableHead className="text-[#8A847C] font-bold uppercase text-[10px] tracking-widest pl-8 py-4">Serviço</TableHead>
                    <TableHead className="text-[#8A847C] font-bold uppercase text-[10px] tracking-widest">Duração</TableHead>
                    <TableHead className="text-[#8A847C] font-bold uppercase text-[10px] tracking-widest">Valor</TableHead>
                    <TableHead className="text-[#8A847C] font-bold uppercase text-[10px] tracking-widest">Anamnese</TableHead>
                    <TableHead className="text-[#8A847C] font-bold uppercase text-[10px] tracking-widest">Manutenção</TableHead>
                    <TableHead className="w-[100px]"></TableHead>
                 </TableRow>
              </TableHeader>
              <TableBody>
                 {loading ? (
                   <TableRow>
                      <TableCell colSpan={6} className="text-center py-20 text-[#5C5855] italic">Carregando serviços...</TableCell>
                   </TableRow>
                 ) : procedures.length === 0 ? (
                   <TableRow>
                      <TableCell colSpan={6} className="text-center py-20 text-[#5C5855] italic">Nenhum serviço cadastrado.</TableCell>
                   </TableRow>
                 ) : (
                   procedures.map((p) => (
                      <TableRow key={p.id} className="border-b border-[#F0EBE0] group hover:bg-[#FAF6E9] transition-colors">
                         <TableCell className="pl-8 py-5">
                            <span className="font-bold text-[#2C2825] text-sm">{p.name}</span>
                         </TableCell>
                         <TableCell>
                            <Badge variant="outline" className="bg-white border-[#E5E0D8] text-[#5C5855] text-[10px] font-bold uppercase">
                               {Math.floor(p.duration_minutes / 60) > 0 ? `${Math.floor(p.duration_minutes / 60)}h ${p.duration_minutes % 60}m` : `${p.duration_minutes}m`}
                            </Badge>
                         </TableCell>
                         <TableCell className="font-mono text-[#2C2825] font-bold">
                            R$ {(p.price || 0).toFixed(2)}
                         </TableCell>
                         <TableCell>
                            {p.requires_anamnese ? (
                               <Badge className="bg-blue-100 text-blue-700 border-none rounded-full w-fit px-2.5">Sim</Badge>
                            ) : (
                               <span className="text-neutral-300 text-xs">-</span>
                            )}
                         </TableCell>
                         <TableCell>
                            {p.maintenance_required ? (
                               <div className="flex flex-col">
                                  <Badge className="bg-emerald-100 text-emerald-700 border-none rounded-full w-fit px-2.5">Sim</Badge>
                                  <span className="text-[10px] text-[#8A847C] mt-1 italic">
                                     {p.maintenance_days_limit} {
                                       p.maintenance_period_unit === 'months' ? (p.maintenance_days_limit === 1 ? 'mês' : 'meses') :
                                       (p.maintenance_days_limit === 1 ? 'dia' : 'dias')
                                     } 
                                     {p.maintenance_duration_minutes > 0 ? ` • ${Math.floor(p.maintenance_duration_minutes / 60) > 0 ? `${Math.floor(p.maintenance_duration_minutes / 60)}h ${p.maintenance_duration_minutes % 60}m` : `${p.maintenance_duration_minutes}m`}` : ''}
                                  </span>
                               </div>
                            ) : (
                               <Badge className="bg-[#F0EBE0] text-[#5C5855] border-none rounded-full w-fit px-2.5">Não</Badge>
                            )}
                         </TableCell>
                         <TableCell className="pr-4 text-right">
                            <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                               {/*<Button size="icon" variant="ghost" className="h-9 w-9 text-[#5C5855] hover:text-[#2C2825] hover:bg-white rounded-xl">
                                  <Edit3 className="h-4 w-4" />
                               </Button>*/}
                               <Button 
                                  size="icon" 
                                  variant="ghost" 
                                  onClick={() => handleDeleteService(p.id)}
                                  className="h-9 w-9 text-[#5C5855] hover:text-red-500 hover:bg-red-50 rounded-xl"
                               >
                                  <Trash2 className="h-4 w-4" />
                               </Button>
                            </div>
                         </TableCell>
                      </TableRow>
                   ))
                 )}
              </TableBody>
           </Table>
        </Card>

        <div className="bg-[#D4AF37]/5 border border-[#D4AF37]/10 rounded-2xl p-6 flex gap-4">
           <div className="p-2 h-fit bg-[#D4AF37]/10 rounded-lg">
              <Info className="h-5 w-5 text-[#D4AF37]" />
           </div>
           <div className="space-y-1">
              <h4 className="text-sm font-bold text-[#2C2825] leading-none">Dica de Gestão</h4>
              <p className="text-xs text-[#5C5855] leading-relaxed">Procedimentos com manutenção configurada gerarão lembretes automáticos na agenda quando estiverem próximos ao vencimento do prazo.</p>
           </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { 
  Card, 
  CardHeader, 
  CardTitle, 
  CardContent, 
  Button, 
  Input, 
  Badge,
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
  cn,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
  Label
} from '@projeto/ui';
import { 
  Settings as SettingsIcon, 
  Building2, 
  Shield, 
  Bell, 
  Trash2, 
  Edit3, 
  Plus,
  ArrowRight,
  Info,
  Mail,
  MessageSquare,
  Smartphone,
  LogOut,
  FileText
} from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { useRouter } from 'next/navigation';
import { useProfile } from '@/providers/profile-provider';

export default function SettingsClient() {
  const [loading, setLoading] = useState(true);
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [activeTab, setActiveTab] = useState<'clinic' | 'security' | 'notifications'>('clinic');
  
  // Security form state
  const [passwordForm, setPasswordForm] = useState({
    newPassword: '',
    confirmPassword: ''
  });

  // Notification form state
  const [notificationPrefs, setNotificationPrefs] = useState({
    newAppointments: true,
    cancellations: true,
    dailySummary: false,
    emailAlerts: true,
    whatsappAlerts: false,
    smsAlerts: false,
    browserPush: true
  });



  const supabase = createBrowserClient();
  const { profile, loading: profileLoading } = useProfile();
  const router = useRouter();
  
  // Use company_id from profile, fallback to empty string if loading
  const companyId = profile?.company_id;

  // File Upload Logic
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [uploadingLogo, setUploadingLogo] = useState(false);

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) {
      alert("O arquivo é muito grande. Máximo de 2MB.");
      return;
    }

    // 1. Optimistic Preview
    const objectUrl = URL.createObjectURL(file);
    setLogoPreview(objectUrl);
    setUploadingLogo(true);

    try {
      // 2. Upload to Supabase Storage
      const fileExt = file.name.split('.').pop();
      const fileName = `${companyId}-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('logos') // Making an educated guess on bucket name
        .upload(filePath, file);

      if (uploadError) {
        // Handle missing bucket specifically
        if (uploadError.message.includes('Bucket not found')) {
           alert("Erro: O bucket 'logos' não existe no Supabase. Crie-o no painel do Supabase com acesso público.");
           throw uploadError;
        }
        throw uploadError;
      }

      // 3. Get Public URL
      const { data: { publicUrl } } = supabase.storage
        .from('logos')
        .getPublicUrl(filePath);

      // 4. Update Company Record
      const { error: dbError } = await supabase
        .from('companies')
        .update({ logo_url: publicUrl })
        .eq('id', companyId);

      if (dbError) throw dbError;

      alert("Logotipo atualizado com sucesso!");

    } catch (error: any) {
      console.error('Error uploading logo:', error);
      alert(`Falha no upload: ${error.message}`);
      // Revert preview on error
      setLogoPreview(null);
    } finally {
      setUploadingLogo(false);
    }
  };

  const fetchProcedures = async () => {
    try {
      setLoading(true);
      // Fetch Company Logo as well
      const { data: companyData, error: companyError } = await supabase
        .from('companies')
        .select('logo_url')
        .eq('id', companyId)
        .single();
      
      if (companyError && companyError.code !== 'PGRST116') throw companyError;
      if (companyData?.logo_url) setLogoPreview(companyData.logo_url);


    } catch (err: any) {
      if (err.message?.includes('AbortError') || err.name === 'AbortError') return;
      console.error('Error fetching settings:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (companyId) {
      fetchProcedures();
    }
  }, [companyId]);

  const handleSignOut = async () => {
    await supabase.auth.signOut();
    router.push('/auth/login');
  };

  const handleUpdatePassword = async () => {
    if (!passwordForm.newPassword || passwordForm.newPassword !== passwordForm.confirmPassword) {
      alert("As senhas não coincidem ou estão vazias!");
      return;
    }
    
    const { error } = await supabase.auth.updateUser({
      password: passwordForm.newPassword
    });

    if (!error) {
      alert("Senha atualizada com sucesso!");
      setPasswordForm({ newPassword: '', confirmPassword: '' });
    } else {
      alert("Erro ao atualizar senha: " + error.message);
    }
  };

  const handleSaveNotifications = async () => {
    // Simulando persistência (Em cenário real, salvar no perfil do usuário no Supabase)
    alert("Preferências de notificação salvas com sucesso!");
  };



  return (
    <div className="space-y-10 animate-fade-in pb-20">
      {/* Header */}
      <div className="flex items-center gap-6">
        <div className="p-3 bg-[#D4AF37]/10 rounded-2xl">
          <SettingsIcon className="h-6 w-6 text-[#D4AF37]" />
        </div>
        <div>
          <h1 className="text-3xl font-black text-[#2C2825] tracking-tight">Configurações Gerais</h1>
          <p className="text-[#8A847C] text-[10px] uppercase font-black tracking-widest mt-1">Personalize seu ambiente de trabalho</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Navigation Sidebar */}
        <div className="space-y-2">
            <NavButton 
              active={activeTab === 'clinic'} 
              onClick={() => setActiveTab('clinic')}
              icon={Building2}
            >
              Dados da Clínica
            </NavButton>
            <NavButton 
              active={activeTab === 'security'} 
              onClick={() => setActiveTab('security')}
              icon={Shield}
            >
              Segurança e Acesso
            </NavButton>
            <NavButton 
              active={activeTab === 'notifications'} 
              onClick={() => setActiveTab('notifications')}
              icon={Bell}
            >
              Notificações
            </NavButton>

            <div className="pt-4 mt-4 border-t border-[#E5E0D8]">
               <button 
                  onClick={handleSignOut}
                  className="w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-red-500 hover:bg-red-50 transition-all font-bold text-sm group"
               >
                  <div className="p-2 bg-red-50 rounded-xl group-hover:bg-red-100 transition-all">
                     <LogOut className="h-4 w-4" />
                  </div>
                  Sair da Conta
               </button>
            </div>
        </div>

        {/* Main Content Areas */}
        <div className="lg:col-span-3 space-y-10">
          
          {activeTab === 'clinic' ? (
            <>
              {/* Company Section */}
              <Card className="bg-white border-[#E5E0D8] rounded-3xl overflow-hidden shadow-sm">
                <CardHeader className="bg-[#FAF6E9] border-b border-[#E5E0D8] p-8">
                  <div className="flex items-center justify-between">
                     <div>
                        <CardTitle className="text-lg font-bold text-[#2C2825]">Dados da Clínica</CardTitle>
                        <p className="text-xs text-[#5C5855] mt-1">Informações básicas que aparecem nos relatórios.</p>
                     </div>
                      <div className="flex items-center gap-4">
                         {isEditingCompany ? (
                            <Button 
                               onClick={() => setIsEditingCompany(false)}
                               className="bg-[#D4AF37] hover:bg-[#B5952F] text-white font-bold rounded-xl h-10 px-6 active:scale-[0.98] transition-all"
                            >
                               Salvar Alterações
                            </Button>
                         ) : (
                            <Button 
                               variant="outline"
                               onClick={() => setIsEditingCompany(true)}
                               className="border-[#E5E0D8] text-[#5C5855] hover:text-[#2C2825] hover:bg-[#FAF6E9] font-bold rounded-xl h-10 px-6 active:scale-[0.98] transition-all"
                            >
                               <Edit3 className="h-4 w-4 mr-2" />
                               Editar Dados
                            </Button>
                         )}
                      </div>
                  </div>
                </CardHeader>
                <CardContent className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Nome Fantasia</label>
                      <Input 
                        defaultValue="Clinica Jamily Premium" 
                        readOnly={!isEditingCompany}
                        className={cn(
                          "bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold transition-all",
                          !isEditingCompany && "opacity-60 cursor-not-allowed border-transparent bg-transparent"
                        )} 
                      />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Telefone Principal</label>
                      <Input 
                        defaultValue="(11) 98765-4321" 
                        readOnly={!isEditingCompany}
                        className={cn(
                          "bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold transition-all",
                          !isEditingCompany && "opacity-60 cursor-not-allowed border-transparent bg-transparent"
                        )} 
                      />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">CNPJ / CPF Especialista</label>
                      <Input 
                        placeholder="00.000.000/0001-00" 
                        readOnly={!isEditingCompany}
                        className={cn(
                          "bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold transition-all",
                          !isEditingCompany && "opacity-60 cursor-not-allowed border-transparent bg-transparent"
                        )} 
                      />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Cidade / Estado</label>
                      <Input 
                        defaultValue="São Paulo, SP" 
                        readOnly={!isEditingCompany}
                        className={cn(
                          "bg-[#FDFBF7] border-[#E5E0D8] h-12 rounded-xl text-[#2C2825] font-bold transition-all",
                          !isEditingCompany && "opacity-60 cursor-not-allowed border-transparent bg-transparent"
                        )} 
                      />
                   </div>
                   
                   {/* Branding Area */}
                    <div className="col-span-full space-y-6 pt-8 border-t border-[#E5E0D8]">
                      <div className="flex items-center gap-2 mb-2">
                         <Building2 className="h-4 w-4 text-[#D4AF37]" />
                         <h4 className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest">Branding da Clínica</h4>
                      </div>
                      <div className="p-8 bg-[#FDFBF7] rounded-3xl border border-[#E5E0D8] border-dashed flex flex-col items-center gap-6">
                         <div className="w-24 h-24 bg-white rounded-3xl flex items-center justify-center border border-[#E5E0D8] overflow-hidden relative group/preview shadow-sm">
                           {logoPreview ? (
                             <>
                               <img src={logoPreview} alt="Logo Preview" className="w-full h-full object-cover" />
                               {uploadingLogo && (
                                 <div className="absolute inset-0 bg-white/50 flex items-center justify-center">
                                    <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-[#D4AF37]"></div>
                                 </div>
                               )}
                             </>
                           ) : (
                             <Plus className="h-8 w-8 text-[#E5E0D8]" />
                           )}
                         </div>
                         <div className="text-center space-y-1">
                            <p className="text-sm font-bold text-[#2C2825]">Carregar Logotipo</p>
                            <p className="text-xs text-[#8A847C] italic">Formatos suportados: SVG, PNG ou JPG (Máx 2MB)</p>
                         </div>
                         <input
                             type="file"
                             accept="image/*"
                             className="hidden"
                             ref={fileInputRef}
                             onChange={handleLogoUpload}
                         />
                         <Button 
                           variant="outline" 
                           className="border-[#E5E0D8] text-[#5C5855] h-10 px-6 font-bold hover:bg-[#FAF6E9] hover:text-[#2C2825]"
                           onClick={() => fileInputRef.current?.click()}
                         >
                           Selecionar Arquivo
                         </Button>
                      </div>
                   </div>
                </CardContent>
              </Card>

            </>
          ) : activeTab === 'security' ? (
            <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
               <Card className="bg-white border-[#E5E0D8] rounded-3xl overflow-hidden shadow-sm">
                  <CardHeader className="bg-[#FAF6E9] border-b border-[#E5E0D8] p-8">
                     <div className="flex items-center justify-between">
                        <div>
                           <CardTitle className="text-lg font-bold text-[#2C2825]">Segurança da Conta</CardTitle>
                           <p className="text-xs text-[#5C5855] mt-1">Gerencie sua senha e acessos.</p>
                        </div>
                        <Shield className="h-6 w-6 text-[#D4AF37] opacity-50" />
                     </div>
                  </CardHeader>
                  <CardContent className="p-8 space-y-8 max-w-2xl">
                     <div className="space-y-6">
                        <div className="space-y-4">
                           <div className="space-y-2">
                              <Label className="text-[10px] font-black text-[#8A847C] uppercase tracking-widest ml-1">Nova Senha</Label>
                              <Input 
                                 type="password"
