'use client';

import { useState, useEffect } from 'react';
import { Button, Input, Card, CardContent, cn, TextArea, Label } from '@projeto/ui';
import { CheckCircle2, AlertCircle, FileText } from 'lucide-react';
import { Toaster, toast } from 'sonner';
import SignatureCanvas from 'react-signature-canvas';
import { useRef } from 'react';

export default function AnamneseForm({ token }: { token: string }) {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<any>(null);
  const [isExternal, setIsExternal] = useState(false);
  const [externalUrl, setExternalUrl] = useState('');
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');
  
  // Novos campos: LGPD e Assinatura
  const [consentAccepted, setConsentAccepted] = useState(false);
  const sigCanvas = useRef<any>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await fetch(`/api/anamnese/public?token=${token}`);
        if (!res.ok) {
           const err = await res.json();
           throw new Error(err.error || 'Erro ao carregar');
        }
        const json = await res.json();
        if (json.template.externalFormUrl) {
          setIsExternal(true);
          setExternalUrl(json.template.externalFormUrl);
        }
        setData(json);
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [token]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validação de obrigatórios
    const missing = data.template.questions.filter((q: any) => q.is_required && !answers[q.id]);
    if (missing.length > 0) {
       toast.error(`Por favor, responda: ${missing[0].question_text}`);
       return;
    }
    // Validação da assinatura e consentimento
    if (!consentAccepted) {
       toast.error('Você precisa aceitar o Termo de Consentimento.');
       return;
    }
    
    if (!sigCanvas.current || sigCanvas.current.isEmpty()) {
       toast.error('Por favor, assine o documento antes de enviar.');
       return;
    }
    
    const signatureDataUrl = sigCanvas.current.getTrimmedCanvas().toDataURL('image/png');

    setSubmitting(true);
    try {
      const res = await fetch('/api/anamnese/public', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, answers, consentAccepted, signatureDataUrl })
      });

      if (!res.ok) throw new Error('Falha ao enviar');
      
      setSubmitted(true);
    } catch (err) {
      toast.error('Erro ao enviar respostas. Tente novamente.');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div className="min-h-screen flex items-center justify-center bg-[#FDFBF7]"><span className="text-[#D4AF37] font-bold animate-pulse">Carregando...</span></div>;

  if (error) return (
     <div className="min-h-screen flex items-center justify-center bg-[#FDFBF7] p-4">
        <Card className="w-full max-w-md border-red-100 bg-white shadow-xl">
           <CardContent className="pt-6 text-center space-y-4">
              <div className="mx-auto w-12 h-12 bg-red-50 rounded-full flex items-center justify-center text-red-500">
                 <AlertCircle className="h-6 w-6" />
              </div>
              <h2 className="text-xl font-bold text-neutral-800">Atenção</h2>
              <p className="text-neutral-500">{error}</p>
           </CardContent>
        </Card>
     </div>
  );

  if (submitted) return (
    <div className="min-h-screen flex items-center justify-center bg-[#FDFBF7] p-4">
        <Card className="w-full max-w-md border-emerald-100 bg-white shadow-xl animate-fade-in">
           <CardContent className="pt-8 pb-8 text-center space-y-6">
              <div className="mx-auto w-16 h-16 bg-emerald-50 rounded-full flex items-center justify-center text-emerald-500 animate-scale-in">
                 <CheckCircle2 className="h-8 w-8" />
              </div>
              <div className="space-y-2">
                 <h2 className="text-2xl font-bold text-neutral-800 font-serif">Obrigado!</h2>
                 <p className="text-neutral-500">Sua anamnese foi recebida com sucesso.</p>
              </div>
              {data.company.name && (
                 <div className="pt-4 border-t border-dashed border-neutral-200">
                    <p className="text-xs uppercase tracking-widest text-[#D4AF37] font-bold">{data.company.name}</p>
                 </div>
              )}
           </CardContent>
        </Card>
    </div>
  );

  if (isExternal) {
    return (
      <div className="min-h-screen bg-[#FDFBF7] py-12 px-4 text-[#2C2825]">
        <div className="max-w-2xl mx-auto text-center space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
           {data?.company?.logo && (
             <img src={data.company.logo} alt={data.company.name} className="h-16 mx-auto mb-8" />
           )}
           <div className="bg-white p-10 rounded-[40px] shadow-xl border border-[#E5E0D8] space-y-6">
              <div className="w-20 h-20 bg-primary-100 rounded-full flex items-center justify-center mx-auto">
                 <FileText className="h-10 w-10 text-primary-600" />
              </div>
              <h1 className="text-3xl font-black uppercase tracking-tighter">Formulário Externo</h1>
              <p className="text-[#5C5855] leading-relaxed">
                Esta ficha de anamnese é respondida em uma plataforma externa ({externalUrl ? new URL(externalUrl).hostname : ''}). 
                Clique no botão abaixo para preencher.
              </p>
              <Button 
                onClick={() => window.location.href = externalUrl}
                className="w-full h-16 bg-primary-600 hover:bg-primary-700 text-white font-black text-lg rounded-2xl shadow-lg shadow-primary-200 transition-all hover:scale-[1.02]"
              >
                ABRIR FORMULÁRIO
              </Button>
              <p className="text-[10px] text-[#8A847C] uppercase font-bold tracking-widest">
                Você será redirecionado para o site parceiro da clínica.
              </p>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FDFBF7] pb-20 font-sans">
      <Toaster position="top-center" />
      
      {/* Header */}
      <div className="bg-white border-b border-[#E5E0D8] sticky top-0 z-10 shadow-sm">
         <div className="max-w-2xl mx-auto px-6 py-4 flex items-center gap-4">
            {data.company.logo && <img src={data.company.logo} className="h-10 w-10 rounded-full object-cover border border-[#E5E0D8]" alt="Logo" />}
            <div>
               <h1 className="text-sm font-bold text-neutral-400 uppercase tracking-widest">{data.company.name}</h1>
               <h2 className="text-lg font-bold text-[#2C2825] font-serif leading-tight">{data.template.title}</h2>
            </div>
         </div>
      </div>

      <main className="max-w-2xl mx-auto px-4 py-8">
         {data.template.description && (
            <div className="bg-[#FAF6E9] border border-[#E5E0D8] p-4 rounded-2xl mb-8 flex gap-3 text-[#5C5855] text-sm">
               <FileText className="h-5 w-5 shrink-0 text-[#D4AF37]" />
               <p>{data.template.description}</p>
            </div>
         )}

         <form onSubmit={handleSubmit} className="space-y-8">
            {data.template.questions.map((q: any) => (
               <div key={q.id} className="space-y-3 bg-white p-6 rounded-3xl border border-[#E5E0D8] shadow-sm hover:shadow-md transition-shadow">
                  <Label className="text-base font-bold text-[#2C2825] flex items-center gap-2">
                     <span className="bg-[#F5F5DC] text-[#8A847C] w-6 h-6 rounded-full flex items-center justify-center text-xs font-black">{q.order}</span>
                     {q.question_text} {q.is_required && <span className="text-red-400 text-xs ml-1">*</span>}
                  </Label>
                  
                  {q.type === 'text_short' && (
                     <Input 
                        placeholder="Sua resposta..." 
                        className="bg-[#FAF9F6] border-[#E5E0D8] h-12 rounded-xl focus:border-[#D4AF37]"
                        value={answers[q.id] || ''}
                        onChange={e => setAnswers({...answers, [q.id]: e.target.value})}
                     />
                  )}

                  {q.type === 'text_long' && (
                     <TextArea
                        placeholder="Descreva detalhadamente..."
                        className="bg-[#FAF9F6] border-[#E5E0D8] min-h-[100px] rounded-xl focus:border-[#D4AF37]"
                        value={answers[q.id] || ''}
                        onChange={e => setAnswers({...answers, [q.id]: e.target.value})}
                     />
                  )}

                  {q.type === 'yes_no' && (
                     <div className="flex gap-4">
                        {['Sim', 'Não'].map(opt => (
                           <button
                              key={opt}
                              type="button"
                              onClick={() => setAnswers({...answers, [q.id]: opt})}
                              className={cn(
                                 "flex-1 py-3 rounded-xl border font-bold transition-all",
                                 answers[q.id] === opt 
                                    ? "bg-[#D4AF37] text-white border-[#D4AF37] shadow-lg shadow-[#D4AF37]/20" 
                                    : "bg-white border-[#E5E0D8] text-[#8A847C] hover:bg-[#FAF9F6]"
                              )}
                           >
                              {opt}
                           </button>
                        ))}

                     </div>
                  )}
                  {/* Outros tipos aqui (date, number, etc) podem ser adicionados conforme a necessidade */}
               </div>
            ))}

             <div className="bg-[#FAF6E9] p-6 rounded-3xl border border-[#E5E0D8] space-y-6">
                <div>
                   <h3 className="text-base font-bold text-[#2C2825] mb-2">Termo de Consentimento</h3>
                   <p className="text-sm text-[#5C5855] leading-relaxed mb-4">
                      Declaro que as informações acima são verdadeiras. Autorizo a clínica a utilizar estes dados estritamente para fins de avaliação e acompanhamento clínico, em conformidade com a Lei Geral de Proteção de Dados (LGPD).
                   </p>
                   <label className="flex items-start gap-3 cursor-pointer group">
                      <div className="pt-0.5">
                         <input 
                            type="checkbox" 
                            className="w-5 h-5 rounded border-[#E5E0D8] text-[#D4AF37] focus:ring-[#D4AF37] cursor-pointer"
                            checked={consentAccepted}
                            onChange={(e) => setConsentAccepted(e.target.checked)}
                         />
                      </div>
                      <span className="text-sm font-bold text-[#2C2825] group-hover:text-[#D4AF37] transition-colors">Li e concordo com o termo de consentimento</span>
                   </label>
                </div>

                <div className="pt-4 border-t border-[#E5E0D8]/50">
                   <h3 className="text-base font-bold text-[#2C2825] mb-2">Assinatura Digital</h3>
                   <p className="text-xs text-[#8A847C] mb-4">Por favor, assine no quadro abaixo usando o mouse ou o dedo.</p>
                   
                   <div className="bg-white border-2 border-dashed border-[#E5E0D8] rounded-2xl overflow-hidden relative touch-none hover:border-[#D4AF37] transition-colors">
                      <SignatureCanvas 
                         ref={sigCanvas}
                         penColor="#2C2825"
                         canvasProps={{
                            className: 'w-full h-40 cursor-crosshair'
                         }}
                      />
                      <button 
                         type="button" 
                         onClick={() => sigCanvas.current?.clear()}
                         className="absolute bottom-2 right-2 px-3 py-1 bg-neutral-100 text-neutral-500 text-xs font-bold rounded-lg hover:bg-neutral-200 transition-colors"
                      >
                         Limpar
                      </button>
                   </div>
                </div>
             </div>

            <div className="pt-6">
                <Button 
                   type="submit" 
                   className="w-full h-14 bg-[#2C2825] hover:bg-black text-[#D4AF37] font-bold text-lg rounded-2xl shadow-xl shadow-black/10"
                   loading={submitting}
                >
                   Finalizar e Enviar
                </Button>
                <p className="text-center text-xs text-neutral-400 mt-4 font-medium uppercase tracking-widest">Seus dados estão protegidos • Agenda Inteligente</p>
            </div>
         </form>
      </main>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { 
  Table, 
  TableHeader, 
  TableBody, 
  TableRow, 
  TableHead, 
  TableCell,
  Badge,
  Button,
  Input,
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem
} from '@projeto/ui';
import { 
  Search, 
  Filter, 
  CheckCircle2, 
  Clock as ClockIcon,
  ArrowRight
} from 'lucide-react';
import Link from 'next/link';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface AccountsReceivableListProps {
  companyId: string;
}

export function AccountsReceivableList({ companyId }: AccountsReceivableListProps) {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<any[]>([]);
  const [filterStatus, setFilterStatus] = useState('pending'); // all, unpaid, partial, confirmed_pending, paid
  const [searchTerm, setSearchTerm] = useState('');
  const [errorHeader, setErrorHeader] = useState<string | null>(null);

  useEffect(() => {
    if (companyId) fetchReceivables();
  }, [companyId]);

    async function fetchReceivables() {
      if (!companyId || companyId === '') {
        setData([]);
        setLoading(false);
        return;
      }

      setLoading(true);
      try {
        const supabase = createBrowserClient();

        const { data: appointments, error: appError } = await supabase
          .from('appointments')
          .select(`
            id,
            start_time,
            status,
            price_override,
            clients (id, full_name),
            procedures (id, name, price)
          `)
          .eq('company_id', companyId)
          .eq('status', 'completed')
          .order('start_time', { ascending: false });

        if (appError) throw appError;

        const appIds = appointments?.map(a => a.id) || [];
        let transactions: any[] = [];

        if (appIds.length > 0) {
          const { data: transData, error: transError } = await supabase
            .from('transactions')
            .select('id, appointment_id, amount, status, type')
            .in('appointment_id', appIds)
            .eq('type', 'income');

          if (transError) throw transError;
          transactions = transData || [];
        }

        const processed = (appointments || []).map(app => {
          const linkedTrans = transactions.filter(t => t.appointment_id === app.id);
          const paidConfirmed = linkedTrans
            .filter(t => t.status === 'completed')
            .reduce((sum, t) => sum + Number(t.amount), 0);

          const hasPendingConfirmation = linkedTrans.some(t => t.status === 'pending');
          const procedure = Array.isArray(app.procedures) ? app.procedures[0] : app.procedures;
          const totalPrice = Number(app.price_override || (procedure as any)?.price || 0);
          const pendingValue = totalPrice - paidConfirmed;

          // Determine logical status
          let status = 'unpaid';
          if (paidConfirmed >= totalPrice && totalPrice > 0) status = 'paid';
          else if (paidConfirmed > 0) status = 'partial';

          // Flatten identifiers for easy filtering/searching
          const client = Array.isArray(app.clients) ? app.clients[0] : app.clients;
          const clientName = (client as any)?.full_name || 'Cliente não identificado';
          const procedureName = (procedure as any)?.name || 'Procedimento não identificado';

          return {
            id: app.id,
            start_time: app.start_time,
            clientName,
            procedureName,
            totalPrice,
            paidConfirmed,
            pendingValue,
            status,
            hasPendingConfirmation,
            displayStatus: hasPendingConfirmation ? 'awaiting_confirmation' : status
          };
        });

        setData(processed);
        setErrorHeader(null);
      } catch (err: any) {
        console.error('Fetch error:', err);
        setErrorHeader(err.message || 'Erro ao carregar dados financeiros.');
      } finally {
        setLoading(false);
      }
    }

  const filteredData = data.filter(item => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = item.clientName.toLowerCase().includes(searchLower) ||
                         item.procedureName.toLowerCase().includes(searchLower);

    if (!matchesSearch) return false;

    switch (filterStatus) {
      case 'all': return true;
      case 'pending': return item.pendingValue > 0;
      case 'unpaid': return item.status === 'unpaid';
      case 'partial': return item.status === 'partial';
      case 'awaiting_confirmation': return item.hasPendingConfirmation;
      case 'paid': return item.status === 'paid';
      default: return true;
    }
  });

  if (loading) return (
    <div className="p-20 text-center">
       <div className="flex flex-col items-center gap-4 animate-pulse">
          <div className="h-10 w-10 bg-slate-100 rounded-full" />
          <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Carregando Pendências...</p>
       </div>
    </div>
  );

  if (errorHeader) return (
    <div className="p-12 text-center bg-rose-50 rounded-[2rem] border border-rose-100">
       <div className="flex flex-col items-center gap-3">
          <div className="p-4 bg-white rounded-2xl shadow-sm text-rose-500">
             <Filter className="h-8 w-8" />
          </div>
          <h3 className="text-rose-900 font-black tracking-tight">Ops! Algo deu errado</h3>
          <p className="text-rose-600/70 text-sm font-medium max-w-xs">{errorHeader}</p>
          <Button 
            className="mt-4 bg-rose-600 hover:bg-rose-700 text-white font-black rounded-xl px-8"
            onClick={fetchReceivables}
          >
            Tentar Novamente
          </Button>
       </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
          <Input 
            placeholder="Buscar por cliente ou procedimento..." 
            className="pl-11 bg-slate-50 border-slate-200 rounded-2xl text-slate-900 h-12 focus:ring-2 focus:ring-rose-500/10 focus:border-rose-500/50 transition-all font-medium placeholder:text-slate-400"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          <Select value={filterStatus} onValueChange={setFilterStatus}>
            <SelectTrigger className="w-full md:w-64 bg-slate-50 border-slate-200 rounded-2xl text-slate-700 h-12 font-bold focus:ring-rose-500/10">
              <div className="flex items-center gap-2">
                <Filter className="h-4 w-4 text-rose-500" />
                <SelectValue placeholder="Filtrar por Status" />
              </div>
            </SelectTrigger>
            <SelectContent className="bg-white border-slate-200 text-slate-700 rounded-2xl shadow-2xl">
              <SelectItem value="pending" className="font-bold py-3 uppercase text-[10px] tracking-widest text-slate-500">Todas as Pendências</SelectItem>
              <SelectItem value="all" className="font-bold py-3 uppercase text-[10px] tracking-widest text-slate-500">Ver Todos</SelectItem>
              <SelectItem value="unpaid" className="font-bold py-3 uppercase text-[10px] tracking-widest text-red-600">❌ Não Pagos</SelectItem>
              <SelectItem value="partial" className="font-bold py-3 uppercase text-[10px] tracking-widest text-amber-600">🕒 Pagos Parcialmente</SelectItem>
              <SelectItem value="awaiting_confirmation" className="font-bold py-3 uppercase text-[10px] tracking-widest text-blue-600">⏳ Confirmando</SelectItem>
              <SelectItem value="paid" className="font-bold py-3 uppercase text-[10px] tracking-widest text-emerald-600">✅ Pagos</SelectItem>
            </SelectContent>
          </Select>

          <Button 
            variant="outline" 
            className="border-slate-200 bg-white text-slate-500 hover:bg-slate-50 rounded-2xl h-12 px-6 font-black uppercase text-[10px] tracking-widest transition-all"
            onClick={fetchReceivables}
          >
            Atualizar
          </Button>
        </div>
      </div>

      <div className="bg-white border border-slate-100 rounded-[2rem] overflow-hidden shadow-sm">
        <Table>
          <TableHeader className="bg-slate-50/80 border-b border-slate-100">
            <TableRow className="hover:bg-transparent border-none">
              <TableHead className="text-[10px] font-black text-slate-400 uppercase tracking-widest py-5 pl-8">Data</TableHead>
              <TableHead className="text-[10px] font-black text-slate-400 uppercase tracking-widest py-5">Cliente / Procedimento</TableHead>
              <TableHead className="text-[10px] font-black text-slate-400 uppercase tracking-widest py-5">Status</TableHead>
              <TableHead className="text-[10px] font-black text-slate-400 uppercase tracking-widest py-5">Valores (R$)</TableHead>
              <TableHead className="text-[10px] font-black text-slate-400 uppercase tracking-widest py-5">Saldo</TableHead>
              <TableHead className="text-right py-5 pr-8"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredData.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} className="h-64 text-center">
                   <div className="flex flex-col items-center gap-4 opacity-40">
                      <div className="p-4 bg-slate-50 rounded-3xl">
                         <Search className="h-10 w-10 text-slate-300" />
                      </div>
                      <p className="text-slate-500 font-black uppercase text-[10px] tracking-tightest">Nenhum registro encontrado.</p>
                   </div>
                </TableCell>
              </TableRow>
            ) : (
              filteredData.map((item) => (
                <TableRow key={item.id} className="border-b border-slate-50 hover:bg-slate-50/50 transition-all cursor-default group">
                  <TableCell className="py-6 pl-8">
                    <div className="flex flex-col">
                      <span className="text-xs font-black text-slate-900">
                        {format(new Date(item.start_time), 'dd/MM', { locale: ptBR })}
                      </span>
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">
                        {format(new Date(item.start_time), 'yyyy', { locale: ptBR })}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="py-6">
                    <p className="font-black text-slate-900 text-sm mb-0.5">{item.clientName}</p>
                    <div className="flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-slate-200" />
                      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tight">{item.procedureName}</p>
                    </div>
                  </TableCell>
                  <TableCell className="py-6">
                    <StatusBadge status={item.displayStatus} />
                  </TableCell>
                  <TableCell className="py-6">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-slate-400 uppercase w-10">Serviço</span>
                        <span className="text-xs font-bold text-slate-600">{new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(item.totalPrice)}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-emerald-500 uppercase w-10">Pago</span>
                        <span className="text-xs font-black text-emerald-600">{new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(item.paidConfirmed)}</span>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell className="py-6">
                    <div className={cn(
                      "inline-flex flex-col px-3 py-1.5 rounded-xl border transition-all",
                      item.pendingValue > 0 
                        ? "bg-rose-50 border-rose-100 text-rose-600 shadow-sm shadow-rose-500/5" 
                        : "bg-emerald-50 border-emerald-100 text-emerald-600"
                    )}>
                      <span className="text-[8px] font-black uppercase tracking-widest mb-0.5 opacity-60">Pendente</span>
                      <span className="text-sm font-black italic">
                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(item.pendingValue)}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="text-right py-6 pr-8">
                    {item.pendingValue > 0 && (
                      <Link href={`/dashboard/finance/new?type=income&appointment_id=${item.id}&amount=${item.pendingValue}&description=Recebimento: ${item.clientName}`}>
                        <Button size="sm" className="bg-slate-950 hover:bg-black text-white font-black rounded-xl text-[10px] uppercase px-5 h-10 shadow-lg shadow-slate-200 active:scale-95 transition-all group-hover:bg-rose-600 transition-colors">
                          Receber
                          <ArrowRight className="ml-2 h-3.5 w-3.5" />
                        </Button>
                      </Link>
                    )}
                    {item.pendingValue <= 0 && (
                       <div className="h-10 w-10 bg-emerald-50 rounded-full flex items-center justify-center ml-auto border border-emerald-100">
                          <CheckCircle2 className="h-5 w-5 text-emerald-500" />
                       </div>
                    )}
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  switch (status) {
    case 'unpaid':
      return (
        <Badge variant="outline" className="bg-rose-50/50 text-rose-600 border-rose-100 text-[10px] font-black uppercase px-3 py-1.5 rounded-xl flex items-center gap-2 w-fit">
          <div className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-pulse" />
          Não Pago
        </Badge>
      );
    case 'partial':
      return (
        <Badge variant="outline" className="bg-amber-50/50 text-amber-600 border-amber-100 text-[10px] font-black uppercase px-3 py-1.5 rounded-xl flex items-center gap-2 w-fit">
          <div className="w-1.5 h-1.5 rounded-full bg-amber-500" />
          Parcial
        </Badge>
      );
    case 'awaiting_confirmation':
      return (
        <Badge variant="outline" className="bg-blue-50/50 text-blue-600 border-blue-100 text-[10px] font-black uppercase px-3 py-1.5 rounded-xl flex items-center gap-2 w-fit">
          <ClockIcon className="h-3.5 w-3.5" />
          Confirmando
        </Badge>
      );
    case 'paid':
      return (
        <Badge variant="outline" className="bg-emerald-50/50 text-emerald-600 border-emerald-100 text-[10px] font-black uppercase px-3 py-1.5 rounded-xl flex items-center gap-2 w-fit">
          <div className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
          Pago
        </Badge>
      );
    default:
      return null;
  }
}

function cn(...classes: any[]) {
  return classes.filter(Boolean).join(' ');
}

'use client';

import { useState, useEffect } from 'react';
import { 
  Button,
  Badge,
  Card,
  CardContent,
  cn
} from '@projeto/ui';
import { 
  Bell, 
  CheckCheck, 
  AlertTriangle, 
  Info, 
  CheckCircle2, 
  Calendar,
  X 
} from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface Notification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'alert' | 'success' | 'reminder';
  is_read: boolean;
  link?: string;
  created_at: string;
}

export default function NotificationBell() {
  const [isOpen, setIsOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);

  const supabase = createBrowserClient();

  const fetchNotifications = async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('profile_id', user.id)
      .order('created_at', { ascending: false })
      .limit(10);

    if (data) {
      setNotifications(data);
      setUnreadCount(data.filter(n => !n.is_read).length);
    }
  };

  useEffect(() => {
    fetchNotifications();

    // Inscrição em tempo real para novas notificações
    const channel = supabase
      .channel('realtime_notifications')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'notifications' },
        (payload) => {
          setNotifications(prev => [payload.new as Notification, ...prev]);
          setUnreadCount(prev => prev + 1);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const markAsRead = async (id: string) => {
    const { error } = await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('id', id);

    if (!error) {
      setNotifications(prev => 
        prev.map(n => n.id === id ? { ...n, is_read: true } : n)
      );
      setUnreadCount(prev => Math.max(0, prev - 1));
    }
  };

  const markAllAsRead = async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    const { error } = await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('profile_id', user.id)
      .eq('is_read', false);

    if (!error) {
      setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
      setUnreadCount(0);
    }
  };

  const getIcon = (type: string) => {
    switch (type) {
      case 'alert': return <AlertTriangle className="h-4 w-4 text-amber-500" />;
      case 'success': return <CheckCircle2 className="h-4 w-4 text-teal-500" />;
      case 'reminder': return <Calendar className="h-4 w-4 text-blue-500" />;
      default: return <Info className="h-4 w-4 text-neutral-500" />;
    }
  };

  return (
    <div className="relative">
      <Button 
        variant="ghost" 
        size="icon" 
        className="relative hover:bg-neutral-100 rounded-full h-10 w-10"
        onClick={() => setIsOpen(!isOpen)}
      >
        <Bell className="h-5 w-5 text-neutral-600" />
        {unreadCount > 0 && (
          <span className="absolute top-2 right-2 flex h-2.5 w-2.5">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-primary-500"></span>
          </span>
        )}
      </Button>

      {isOpen && (
        <>
          <div 
            className="fixed inset-0 z-40 bg-black/5" 
            onClick={() => setIsOpen(false)} 
          />
          <Card className="absolute right-0 mt-2 w-80 z-50 shadow-2xl border-neutral-200 animate-in fade-in slide-in-from-top-2 duration-200">
            <div className="p-4 border-b flex items-center justify-between bg-neutral-50/50">
              <h3 className="font-bold text-neutral-900">Notificações</h3>
              <div className="flex items-center gap-1">
                {unreadCount > 0 && (
                  <Button 
                    variant="ghost" 
                    size="sm" 
                    className="h-8 text-[11px] uppercase font-bold text-primary-600 hover:text-primary-700"
                    onClick={markAllAsRead}
                  >
                    Marcar todas lidas
                  </Button>
                )}
                <Button 
                  variant="ghost" 
                  size="icon" 
                  className="h-8 w-8 text-neutral-400 hover:text-neutral-600"
                  onClick={() => setIsOpen(false)}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </div>
            <CardContent className="p-0 max-h-[400px] overflow-y-auto">
              {notifications.length === 0 ? (
                <div className="p-10 text-center text-neutral-400">
                  <Bell className="h-8 w-8 mx-auto mb-2 opacity-20" />
                  <p className="text-sm">Nenhuma notificação por aqui.</p>
                </div>
              ) : (
                <div className="divide-y">
                  {notifications.map((n) => (
                    <div 
                      key={n.id} 
                      className={cn(
                        "p-4 transition-colors hover:bg-neutral-50 relative group",
                        !n.is_read && "bg-primary-50/30"
                      )}
                      onClick={() => !n.is_read && markAsRead(n.id)}
                    >
                      <div className="flex gap-3">
                        <div className="mt-0.5">{getIcon(n.type)}</div>
                        <div className="flex-1 space-y-1">
                          <p className={cn("text-sm font-bold", n.is_read ? "text-neutral-700" : "text-neutral-900")}>
                            {n.title}
                          </p>
                          <p className="text-xs text-neutral-500 leading-relaxed">
                            {n.message}
                          </p>
                          <p className="text-[10px] text-neutral-400 uppercase font-bold pt-1">
                            {format(new Date(n.created_at), "dd MMM · HH:mm", { locale: ptBR })}
                          </p>
                        </div>
                        {!n.is_read && (
                          <div className="w-2 h-2 bg-primary-500 rounded-full mt-1.5" />
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
            {notifications.length > 0 && (
              <div className="p-3 border-t text-center bg-neutral-50/30">
                <Button variant="ghost" size="sm" className="w-full text-xs text-neutral-500">
                  Ver todas as notificações
                </Button>
              </div>
            )}
          </Card>
        </>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, cn } from '@projeto/ui';
import { Star, TrendingUp, Calendar, ChevronLeft, ChevronRight, MessageSquare } from 'lucide-react';
import { createBrowserClient } from '@/lib/supabase-browser';

export function ReviewsWidget() {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<any[]>([]);
  const [reviews, setReviews] = useState<any[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const supabase = createBrowserClient();

  useEffect(() => {
    async function fetchData() {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from('profiles')
        .select('company_id')
        .eq('id', user.id)
        .single();

      if (!profile) return;

      // 1. Buscar métricas agrupadas (seria ideal via RPC, mas faremos no client para simplicidade inicial)
      const { data: allReviews } = await supabase
        .from('appointment_reviews')
        .select('*')
        .eq('company_id', profile.company_id)
        .order('created_at', { ascending: false });

      if (allReviews) {
        // Agrupar por Mês/Ano
        const grouped = allReviews.reduce((acc: any, review) => {
          const key = `${review.review_year}-${String(review.review_month).padStart(2, '0')}`;
          if (!acc[key]) {
            acc[key] = {
              month: review.review_month,
              year: review.review_year,
              total: 0,
              sum: 0,
              reviews: []
            };
          }
          acc[key].total += 1;
          acc[key].sum += review.rating;
          acc[key].reviews.push(review);
          return acc;
        }, {});

        const statsArray = Object.values(grouped).sort((a: any, b: any) => 
          b.year !== a.year ? b.year - a.year : b.month - a.month
        );

        setStats(statsArray);
        setReviews(allReviews.slice(0, 5)); // Mostrar as 5 últimas no geral
      }
      setLoading(false);
    }

    fetchData();
  }, []);

  if (loading) return <div className="h-64 flex items-center justify-center text-muted-foreground animate-pulse">Carregando métricas...</div>;

  if (stats.length === 0) return (
    <Card className="bg-muted/10 border-dashed border-2">
      <CardContent className="py-12 text-center text-muted-foreground">
         <MessageSquare className="w-12 h-12 mx-auto mb-4 opacity-20" />
         <p>Nenhuma avaliação recebida até o momento.</p>
      </CardContent>
    </Card>
  );

  const currentMonth = stats[currentIndex];
  const avgRating = (currentMonth.sum / currentMonth.total).toFixed(1);
  const monthName = new Date(currentMonth.year, currentMonth.month - 1).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-7">
        <Card className="col-span-3 bg-gradient-to-br from-primary/10 to-transparent border-primary/20 overflow-hidden relative group">
          <div className="absolute top-4 right-4 flex gap-2">
             <button 
                onClick={() => setCurrentIndex(prev => Math.min(stats.length - 1, prev + 1))}
                disabled={currentIndex === stats.length - 1}
                className="p-1 rounded-full hover:bg-primary/20 disabled:opacity-30 transition-colors"
             >
                <ChevronLeft className="w-5 h-5" />
             </button>
             <button 
                onClick={() => setCurrentIndex(prev => Math.max(0, prev - 1))}
                disabled={currentIndex === 0}
                className="p-1 rounded-full hover:bg-primary/20 disabled:opacity-30 transition-colors"
             >
                <ChevronRight className="w-5 h-5" />
             </button>
          </div>
          
          <CardHeader>
            <div className="flex items-center gap-2 text-primary font-bold uppercase tracking-widest text-[10px]">
               <Calendar className="w-3 h-3" />
               {monthName}
            </div>
            <CardTitle className="text-2xl font-serif">Métricas Mensais</CardTitle>
          </CardHeader>
          <CardContent className="flex flex-col items-center justify-center py-6">
            <div className="text-7xl font-bold text-primary font-serif drop-shadow-sm">{avgRating}</div>
            <div className="flex gap-1.5 my-4">
              {[1, 2, 3, 4, 5].map((s) => (
                <Star key={s} className={`w-6 h-6 ${s <= Math.round(Number(avgRating)) ? 'fill-primary text-primary' : 'text-primary/20'}`} />
              ))}
            </div>
            <div className="flex items-center gap-2 text-sm text-muted-foreground font-medium">
               <TrendingUp className="w-4 h-4 text-emerald-500" />
               {currentMonth.total} avaliações no mês
            </div>
          </CardContent>
        </Card>

        <Card className="col-span-4 border-[#E5E0D8]">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="font-serif">Últimos Feedbacks</CardTitle>
            <MessageSquare className="w-5 h-5 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {reviews.map((review) => (
                <div key={review.id} className="border-b border-[#F5F2EF] pb-4 last:border-0 last:pb-0 animate-in fade-in slide-in-from-right-4 duration-500">
                  <div className="flex justify-between items-start">
                    <div className="flex-1 space-y-1">
                      <div className="flex items-center gap-2">
                         <h4 className="font-bold text-sm text-[#2C2825]">Cliente</h4>
                         <span className="text-[10px] text-muted-foreground uppercase">{new Date(review.created_at).toLocaleDateString('pt-BR')}</span>
                      </div>
                      <p className="text-xs text-[#5C5855] italic leading-relaxed">"{review.comment || 'Sem comentário'}"</p>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                      <div className="flex gap-0.5">
                        {[1, 2, 3, 4, 5].map((s) => (
                          <Star key={s} className={`w-3.5 h-3.5 ${s <= review.rating ? 'fill-[#D4AF37] text-[#D4AF37]' : 'text-neutral-200'}`} />
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
         {stats.slice(0, 4).map((m, idx) => (
            <Card key={idx} className={cn("bg-card transition-all cursor-pointer hover:border-primary", currentIndex === idx && "ring-2 ring-primary border-transparent")}>
               <CardContent className="p-4 py-6 text-center" onClick={() => setCurrentIndex(idx)}>
                  <p className="text-[10px] font-bold uppercase text-muted-foreground mb-1">
                    {new Date(m.year, m.month - 1).toLocaleDateString('pt-BR', { month: 'short' })} {m.year}
                  </p>
                  <p className="text-2xl font-serif font-bold text-primary">{(m.sum / m.total).toFixed(1)}</p>
                  <p className="text-[10px] text-muted-foreground">{m.total} feedbacks</p>
               </CardContent>
            </Card>
         ))}
      </div>
    </div>
  );
}

'use client';

import { useState, useRef } from 'react';
import { 
  Card, 
  CardHeader, 
  CardTitle, 
  CardContent, 
  Button, 
  TextArea,
  Badge,
  cn
} from '@projeto/ui';
import { 
  FileText, 
  Plus, 
  Clock, 
  User, 
  CheckCircle2,
  Calendar,
  Image as ImageIcon,
  Stethoscope,
  ClipboardList,
  Upload,
  Camera
} from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { createBrowserClient } from '@/lib/supabase-browser';
import { toast } from 'sonner';

interface MedicalRecord {
  id: string;
  type: 'legacy' | 'progress' | 'appointment_record' | 'anamnese' | 'attachment';
  content?: string;
  progress_notes?: string;
  clinical_notes?: string;
  procedure_performed?: string;
  materials_used?: string;
  complications?: string;
  template?: { name: string };
  appointment?: { procedures: { name: string } };
  file_url?: string;
  file_type?: string;
  description?: string;
  status?: string;
  created_at: string;
  professional?: {
    full_name: string;
  };
}

interface MedicalTimelineProps {
  records: MedicalRecord[];
  clientId: string;
  companyId: string;
  professionalId: string;
  onAddRecord: (content: string) => Promise<void>;
  isSubmitting?: boolean;
}

export default function MedicalTimeline({ 
  records, 
  clientId,
  companyId,
  professionalId,
  onAddRecord,
  isSubmitting = false
}: MedicalTimelineProps) {
  const [newRecordContent, setNewRecordContent] = useState('');
  const [isExpanding, setIsExpanding] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = async () => {
    if (!newRecordContent.trim()) return;
    await onAddRecord(newRecordContent);
    setNewRecordContent('');
    setIsExpanding(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const supabase = createBrowserClient();
    
    try {
      const fileName = `${clientId}/${Date.now()}_${file.name}`;
      const { data: uploadData, error: uploadError } = await supabase.storage
        .from('clinical_attachments')
        .upload(fileName, file);

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from('clinical_attachments')
        .getPublicUrl(fileName);

      const { error: dbError } = await supabase
        .from('medical_attachments')
        .insert({
          company_id: companyId,
          client_id: clientId,
          uploaded_by: (await supabase.auth.getUser()).data.user?.id,
          file_url: publicUrl,
          file_type: file.type,
          description: file.name
        });

      if (dbError) throw dbError;

      toast.success('Arquivo enviado com sucesso!');
      window.location.reload(); // Refresh to show new attachment
    } catch (error: any) {
      console.error('Error uploading file:', error);
      toast.error('Erro ao enviar arquivo: ' + error.message);
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="space-y-8 max-w-4xl mx-auto">
      {/* New Record Action */}
      <div className="flex gap-4">
        {!isExpanding ? (
          <Button 
            onClick={() => setIsExpanding(true)} 
            className="flex-1 h-16 border-dashed border-2 bg-transparent hover:bg-primary-50 text-primary-600 border-primary-200"
          >
            <Plus className="h-5 w-5 mr-2" />
            Nova Evolução Clínica
          </Button>
        ) : null}

        <Button 
          variant="outline"
          onClick={() => fileInputRef.current?.click()} 
          loading={isUploading}
          className="flex-1 h-16 border-dashed border-2 bg-transparent hover:bg-emerald-50 text-emerald-600 border-emerald-200"
        >
          <Camera className="h-5 w-5 mr-2" />
          Anexar Foto / Documento
        </Button>
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleFileUpload} 
          className="hidden" 
          accept="image/*,application/pdf"
        />
      </div>

      {isExpanding && (
        <Card className="border-primary-200 shadow-md animate-in fade-in zoom-in duration-200">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold flex items-center gap-2">
              <FileText className="h-4 w-4 text-primary-500" />
              Nova Entrada no Prontuário
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <TextArea 
              placeholder="Descreva a evolução do paciente, procedimentos realizados e observações clínicas..."
              className="min-h-[200px] text-base"
              value={newRecordContent}
              onChange={(e) => setNewRecordContent(e.target.value)}
            />
            <div className="flex justify-end gap-3">
              <Button variant="secondary" onClick={() => setIsExpanding(false)}>
                Cancelar
              </Button>
              <Button 
                onClick={handleSubmit} 
                loading={isSubmitting}
                disabled={!newRecordContent.trim()}
              >
                Salvar Evolução
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Timeline */}
      <div className="relative space-y-6 before:absolute before:inset-0 before:ml-5 before:-translate-x-px before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-neutral-200 before:to-transparent">
        {records.length === 0 && !isExpanding && (
          <div className="pl-12 py-8 text-neutral-500 italic">
            Nenhum registro clínico encontrado para este paciente.
          </div>
        )}

        {records.map((record) => (
          <div key={record.id} className="relative pl-12">
            {/* Timeline Dot */}
            <div className={cn(
               "absolute left-0 w-10 h-10 bg-white border-2 rounded-full flex items-center justify-center z-10 shadow-sm",
               record.type === 'anamnese' ? "border-amber-500 text-amber-500" :
               record.type === 'attachment' ? "border-emerald-500 text-emerald-500" :
               record.type === 'appointment_record' ? "border-blue-500 text-blue-500" :
               "border-primary-500 text-primary-500"
            )}>
              {record.type === 'anamnese' && <ClipboardList className="h-5 w-5" />}
              {record.type === 'attachment' && <ImageIcon className="h-5 w-5" />}
              {record.type === 'appointment_record' && <Stethoscope className="h-5 w-5" />}
              {(record.type === 'legacy' || record.type === 'progress') && <CheckCircle2 className="h-5 w-5" />}
            </div>

            <Card className="hover:shadow-md transition-shadow">
              <CardContent className="pt-6">
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center gap-4 text-sm text-neutral-500">
                    <span className="flex items-center gap-1 font-medium text-neutral-900">
                      <Calendar className="h-4 w-4" />
                      {format(new Date(record.created_at), "dd 'de' MMMM, yyyy", { locale: ptBR })}
                    </span>
                    <span className="flex items-center gap-1">
                      <Clock className="h-4 w-4" />
                      {format(new Date(record.created_at), "HH:mm")}
                    </span>
                    {record.professional && (
                      <span className="flex items-center gap-1 bg-neutral-100 px-2 py-0.5 rounded-full">
                        <User className="h-3 w-3" />
                        {record.professional.full_name}
                      </span>
                    )}
                  </div>
                  <Badge variant={
                    record.type === 'anamnese' ? 'warning' :
                    record.type === 'attachment' ? 'success' :
                    record.type === 'appointment_record' ? 'default' :
                    'secondary'
                  }>
                    {record.type === 'anamnese' && 'Anamnese'}
                    {record.type === 'attachment' && 'Anexo'}
                    {record.type === 'appointment_record' && 'Atendimento'}
                    {record.type === 'legacy' && 'Nota Geral'}
                    {record.type === 'progress' && 'Evolução'}
                  </Badge>
                </div>
                
                <div className="space-y-4">
                  {/* Rendering based on type */}
                  {(record.type === 'legacy' || record.type === 'progress') && (
                    <div className="prose prose-sm max-w-none text-neutral-700 whitespace-pre-wrap leading-relaxed">
                      {record.content || record.progress_notes}
                    </div>
                  )}

                  {record.type === 'appointment_record' && (
                    <div className="space-y-3">
                       <h4 className="font-bold text-blue-700 text-sm uppercase tracking-wider">
                          Procedimento: {record.appointment?.procedures?.name || 'Não informado'}
                       </h4>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                          <div className="space-y-1">
                             <p className="font-bold text-neutral-500 uppercase text-[10px]">Notas Clínicas</p>
                             <p className="text-neutral-700">{record.clinical_notes || '-'}</p>
                          </div>
                          <div className="space-y-1">
                             <p className="font-bold text-neutral-500 uppercase text-[10px]">Materiais</p>
                             <p className="text-neutral-700">{record.materials_used || '-'}</p>
                          </div>
                       </div>
                       {record.complications && (
                          <div className="p-3 bg-red-50 border border-red-100 rounded-xl text-red-700 text-xs">
                             <p className="font-bold mb-1">COMPLICAÇÕES:</p>
                             <p>{record.complications}</p>
                          </div>
                       )}
                    </div>
                  )}

                  {record.type === 'anamnese' && (
                    <div className="flex items-center justify-between p-4 bg-amber-50 border border-amber-100 rounded-2xl">
                       <div className="flex items-center gap-3">
                          <ClipboardList className="h-5 w-5 text-amber-600" />
                          <div>
                             <p className="font-bold text-amber-900">{record.template?.name}</p>
                             <p className="text-xs text-amber-700">Respondida pelo paciente</p>
                          </div>
                       </div>
                       <Button size="sm" variant="outline" className="border-amber-200 text-amber-700 hover:bg-amber-100" onClick={() => window.open(`/api/anamnese/export-pdf?response_id=${record.id}`, '_blank')}>
                          Ver PDF
                       </Button>
                    </div>
                  )}

                  {record.type === 'attachment' && (
                    <div className="space-y-3">
                       {record.file_type?.startsWith('image/') ? (
                          <img 
                            src={record.file_url} 
                            alt={record.description} 
                            className="rounded-2xl border border-neutral-100 max-h-[400px] w-auto shadow-sm"
                          />
                       ) : (
                          <div className="flex items-center gap-3 p-4 bg-emerald-50 border border-emerald-100 rounded-2xl">
                             <Upload className="h-5 w-5 text-emerald-600" />
                             <p className="font-medium text-emerald-900">{record.description}</p>
                          </div>
                       )}
                       {record.description && record.file_type?.startsWith('image/') && (
                         <p className="text-xs text-neutral-500 italic">{record.description}</p>
                       )}
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          </div>
        ))}
      </div>
    </div>
  );
}

