        <svg
          width={size}
          height={size}
          viewBox="0 0 100 100"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          {/* Golden Geometric Shape */}
          <path
            d="M50 10 L70 30 L70 50 L50 70 L30 50 L30 30 Z"
            fill="#D4AF37"
            opacity="0.9"
          />
          <path
            d="M50 20 L65 35 L65 50 L50 65 L35 50 L35 35 Z"
            fill="#2C2825"
            opacity="0.8"
          />
          <path
            d="M50 30 L60 40 L60 50 L50 60 L40 50 L40 40 Z"
            fill="#D4AF37"
            opacity="0.7"
          />
        </svg>
      </div>
      
      {showText && (
        <div className="flex flex-col leading-none">
          <span className="text-sm font-bold text-[#2C2825]">AGENDA</span>
          <span className="text-sm font-bold text-[#D4AF37]">INTELIGENTE</span>
        </div>
      )}
    </div>
  );
}

export function LogoImage({ className, size = 40, src }: LogoProps & { src?: string | null }) {
  const finalSrc = src || "/images/logo.jpg";

  return (
    <div 
      className={`relative flex items-center justify-center overflow-hidden rounded-xl border border-dashed border-amber-200 ${className || ''}`} 
      style={{ width: size * 3, height: size * 1.2 }}
    >
      <img
        src={finalSrc}
        alt="Logo"
        className="w-full h-full object-contain"
        onError={(e) => {
          e.currentTarget.style.display = 'none';
          e.currentTarget.parentElement!.innerHTML += '<span class="text-[10px] font-bold text-amber-600">Logo</span>';
        }}
      />
    </div>
  );
}

'use client';

import React, { createContext, useContext, useEffect, useState } from 'react';
import { createBrowserClient } from '@/lib/supabase-browser';
import { Profile } from '@/types/database';
import { PostgrestError } from '@supabase/supabase-js';

interface ProfileContextType {
  profile: Profile | null;
  loading: boolean;
  error: any | null;
  refreshProfile: () => Promise<void>;
}

const ProfileContext = createContext<ProfileContextType | undefined>(undefined);

export function ProfileProvider({ children }: { children: React.ReactNode }) {
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<any | null>(null);
  const supabase = createBrowserClient();

  const fetchProfile = async () => {
    let userId: string | undefined;

    try {
      setLoading(true);
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        setProfile(null);
        return;
      }
      userId = user.id;

      const { data, error: fetchError } = await supabase
        .from('profiles')
        .select('*, companies(*)')
        .eq('id', user.id)
        .single();

      if (fetchError) throw fetchError;
      setProfile(data);
    } catch (err) {
      const pgError = err as PostgrestError;
      
      // Handle "Row not found" (PGRST116) - Warn only, do not error
      if (pgError?.code === 'PGRST116') {
        console.warn('Profile sync: User has no profile data (PGRST116). This is expected for new users until they complete setup.');
        setProfile(null);
        return;
      }

      // Handle AbortError (network cancellation)
      // Check for strictly standard AbortError OR specific Supabase/Fetch abort messages
      const isAbort = 
        (err instanceof Error && err.name === 'AbortError') ||
        (err instanceof Error && err.message?.includes('AbortError')) ||
        (typeof err === 'object' && err !== null && 'message' in err && (err as any).message?.includes('AbortError'));

      if (isAbort) {
        // Request was aborted (component unmount or fast navigation), ignore.
        return;
      }

      // Handle missing table
      if (pgError?.code === '42P01') {
        console.error('CRITICAL: Missing table "profiles". Run database setup scripts.');
      } else {
        // Log other unexpected errors
        const errorMessage = err instanceof Error ? err.message : JSON.stringify(err, null, 2);
        console.error('Error fetching profile for user:', userId || 'unknown', errorMessage);
      }

      setError(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProfile();

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(() => {
      fetchProfile();
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  return (
    <ProfileContext.Provider 
      value={{ 
        profile, 
        loading, 
        error, 
        refreshProfile: fetchProfile 
      }}
    >
      {children}
    </ProfileContext.Provider>
  );
}

export function useProfile() {
  const context = useContext(ProfileContext);
  if (context === undefined) {
    throw new Error('useProfile must be used within a ProfileProvider');
  }
  return context;
}
